// СГЕНЕРИРОВАНО tools/gen_rules_text.py — правь генератор, не этот файл.
// Умения подклассов на уровне их выбора — для предпросмотра (режим B). Грузится лениво.

export const RULES_SUBPREV = {"subprev:Бард:Коллегия доблести":{"title":"Коллегия доблести","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Дополнительные навыки"},{"p":"Присоединяясь к коллегии доблести, вы получаете владение средними доспехами, щитами и воинским оружием."},{"h":"Боевое вдохновение"},{"p":"Вы узнаёте, как вдохновлять других в бою. Существо, получившее от вас кость бардовского вдохновения, может бросить эту кость и добавить результат к своему броску урона оружием. В качестве альтернативы, если существо атаковано, оно может реакцией совершить бросок кости вдохновения и добавить результат к своему КД от этой атаки. Оно может сделать это после броска атаки, но до того, как узнает, попали ли по нему."}]},"subprev:Бард:Коллегия знаний":{"title":"Коллегия знаний","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Дополнительные навыки"},{"p":"Если вы присоединяетесь к коллегии знаний, вы овладеваете тремя навыками на ваш выбор."},{"h":"Острое словцо"},{"p":"Вы узнаёте, как использовать собственное остроумие, чтобы отвлечь, смутить или по-другому подорвать способности и уверенность противников. Если существо, которое вы можете видеть, в пределах 60 футов от вас совершает бросок атаки, урона или проверку характеристики, вы можете реакцией потратить одну из ваших костей бардовского вдохновения, и вычесть результат броска этой кости из броска этого существа. Вы можете принять решение об использовании этого умения после броска существа, но до того момента, когда Мастер объявит результат броска или проверки. Существо не подвержено этому умению, если не может слышать вас, или обладает иммунитетом к очарованию."}]},"subprev:Бард:Коллегия мечей":{"title":"Коллегия мечей","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Боевой стиль"},{"p":"Вы выбираете боевой стиль, соответствующий вашей специализации. Выберите один из следующих вариантов. Вы не можете выбирать один и тот же вариант боевого стиля, даже если позже у вас будет возможность выбрать ещё один стиль."},{"p":"Дуэлянт. Пока вы держите рукопашное оружие в одной руке и не используете другого оружия, вы получаете бонус +2 к броскам урона этим оружием."},{"p":"Сражение двумя оружиями. Если вы сражаетесь двумя оружиями, вы можете добавить модификатор характеристики к урону от второй атаки."},{"h":"Дополнительные владения"},{"p":"Когда вы вступаете в Коллегию Мечей, вы получаете владение средними доспехами и скимитарами. Если вы владеете простым или воинским оружием ближнего боя, то можете использовать его в качестве фокусировки для ваших заклинаний барда."},{"p":"росчерк клинка"},{"p":"Вы учитесь исполнять впечатляющие демонстрации боевого мастерства и проворства. Когда вы совершаете действие Атака в свой ход, ваша скорость ходьбы увеличивается на 10 футов до конца хода, а если атака оружием, которую вы совершаете частью этого действия, попадает по существу, вы можете использовать один из следующих вариантов «Росчерка клинка» по своему выбору. Вы можете использовать только один вариант «Росчерка клинка» за ход."},{"p":"Оборонительный росчерк. Вы можете потратить одно свое «Вдохновение барда», чтобы оружие нанесло дополнительный урон по цели. Урон равен числу, выпавшему на кости бардовского вдохновения. Вы также добавляете это число к своему КД до начала своего следующего хода."},{"p":"Режущий росчерк. Вы можете потратить одно свое «Вдохновение барда», чтобы оружие нанесло дополнительный урон по цели и по любому другому существу по вашему выбору, которое вы можете видеть в 5 футах от себя. Урон равен числу, выпавшему на кости бардовского вдохновения."},{"p":"Мобильный росчерк. Вы можете потратить одно свое «Вдохновение барда», чтобы оружие нанесло дополнительный урон по цели. Урон равен числу, выпавшему на кости бардовского вдохновения. Вы также можете оттолкнуть цель на 5 футов от себя, плюс количество футов, выпавшее на кости бардовского вдохновения. После этого вы незамедлительно можете реакцией переместиться на расстояние не большее своей скорости в незанятое место в 5 футах от цели."}]},"subprev:Бард:Коллегия очарования":{"title":"Коллегия очарования","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Завораживающее выступление"},{"p":"Вы можете наполнить свое выступление притягательными чарами фей. Если вы выступаете как минимум в течение 1 минуты, то можете попытаться очаровать слушателей своим пением, чтением стихотворения или танцем. В конце выступления выберите такое число Гуманоидов в пределах 60 футов от вас, которые смотрели и слушали все выступление, количество которых не превышает ваш модификатор Харизмы (минимум 1)."},{"p":"Каждая цель должна преуспеть в спасброске Мудрости против Сл спасброска от ваших заклинаний, иначе будет очарована вами. Очарованные таким образом существа боготворят вас и говорят о вас крайне восторженно с любым заговорившим с ними. Они мешают вашим недругам, хотя при этом избегают насилия, если только к этому моменту уже и так не были настроены драться за вас."},{"p":"Эффект на цели заканчивается через 1 час, если цель получает любой урон, если вы атакуете её или если она замечает, как вы атакуете или наносите урон кому-то из её союзников. Если цель преуспевает в спасброске, то она не замечает никаких признаков того, что вы пытались её очаровать."},{"p":"Использовав это умение, вы не можете использовать его повторно до окончания короткого или продолжительного отдыха."},{"h":"Мантия вдохновения"},{"p":"Вступая в коллегию очарования, вы получаете возможность слагать песни, сплетённые с чарами фей, которые наполняют ваших союзников отвагой и проворством."},{"p":"Вы можете бонусным действием потратить одно использование своего «Вдохновения барда», чтобы придать себе поразительный внеземной облик. Когда вы делаете это, выберите несколько союзников, которых вы можете видеть, и которые могут видеть вас в пределах 60 футов от вас. Количество выбранных целей не должно превышать ваш модификатор Харизмы (минимум 1)."},{"p":"Каждая выбранная цель получает 5 временных хитов. Когда цель получает временные хиты от этого умения, она также немедленно может реакцией переместиться на расстояние, не превышающее своей скорости, не вызывая провоцированных атак."},{"p":"Количество временных хитов увеличивается, когда вы достигаете определенных уровней в этом классе: до 8 на 5-м уровне, 11 на 10-м уровне и 14 на 15-м уровне."}]},"subprev:Бард:Коллегия шёпотов":{"title":"Коллегия шёпотов","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Психические клинки"},{"p":"При вступлении в коллегию шёпотов вы получаете возможность сделать свою атаку оружием магически токсичной для разума существа. Когда вы попадаете по существу атакой оружием, вы можете потратить одно «Вдохновение барда» и нанести цели дополнительные 2к6 урона психической энергией. Вы можете использовать это умение один раз за раунд в свой ход."},{"p":"Урон психической энергией увеличивается, когда вы получаете определенный уровень в этом классе, увеличиваясь до 3к6 на 5-м уровне, 5к6 на 10-м уровне и 8к6 на 15-м уровне."},{"h":"Слова ужаса"},{"p":"Вы учитесь наполнять кажущиеся безобидными слова коварной магией, которая вызывает ужас. Если вы разговариваете с Гуманоидом наедине, в течение по крайней мере 1 минуты, то можете попытаться посеять семя паранойи в его разуме."},{"p":"В конце беседы цель должна преуспеть в спасброске Мудрости против вашей Сл спасброска от ваших заклинаний, иначе будет напугана вами или другим существом по вашему выбору. Цель напугана на 1 час таким образом, пока не будет атакована или не получит урон, или пока она не заметит, что её союзники атакованы или получили урон. Если цель преуспевает в спасброске, то она не замечает никаких признаков того, что вы пытались ее испугать."},{"p":"Использовав это умение, вы не можете использовать его повторно до окончания короткого или продолжительного отдыха."}]},"subprev:Бард:Коллегия созидания":{"title":"Коллегия созидания","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Частица потенциала"},{"p":"Всякий раз, когда вы даете существу кость бардовского вдохновения, вы можете произнести ноту из Песни Созидания, чтобы создать Крошечную частицу потенциала, которая будет вращаться вокруг существа на расстоянии 5 футов. Частица неосязаема и неуязвима, и она не исчезнет, пока кость бардовского вдохновения не будет потрачена. Частица выглядит как музыкальная нота, звезда, цветок или другой символ искусства или жизни, который вы выбираете."},{"p":"Когда существо использует кость бардовского вдохновения, частица создает дополнительный эффект, основанный на том, приносит ли кость пользу проверке характеристики, броску атаки или спасброску, как сказано ниже:"},{"p":"Проверка характеристики. Когда существо бросает кость бардовского вдохновения, чтобы добавить его к проверке характеристики, частица проявляется и на мгновение испускает красочные, безвредные искры, а существо может снова бросить кость бардовского вдохновения и выбрать, какой результат использовать."},{"p":"Бросок атаки. Сразу же после того, как существо бросает кость бардовского вдохновения, чтобы добавить её к броску атаки против цели, частица с грохотом разбивается. Цель и каждое существо по вашему выбору, которое вы можете видеть в пределах 5 футов от неё, должны преуспеть в спасброске Телосложения против Сл ваших заклинаний, иначе получат урон звуком, равный значению, выпавшему на кости бардовского вдохновения."},{"p":"Спасбросок. Сразу же после того, как существо бросает кость бардовского вдохновения и добавляет её к спасброску, частица исчезает со звуками мягкой музыки, в результате чего существо получает количество временных хитов, равное значению, выпавшему на кости бардовского вдохновения, плюс ваш модификатор Харизмы (минимум 1 временный хит)."},{"h":"Созидательное выступление"},{"p":"Действием вы можете направить магию Песни Созидания для создания одного немагического предмета по вашему выбору в свободном пространстве в пределах 10 футов от вас. Предмет должен находиться на поверхности или в жидкости, которая может поддерживать его на плаву. Стоимость предмета в зм не может быть более чем в 20 раз больше вашего уровня барда, а размер должен быть Средним или меньше. Предмет слегка мерцает, а коснувшись его, можно услышать слабую музыку. Созданный предмет исчезает через количество часов, равное вашему бонусу мастерства. Примеры предметов, которые вы можете создать, смотрите в главе «Снаряжение» «Книги игрока»."},{"p":"После того, как вы создадите предмет этим умением, вы не сможете сделать это снова, пока не закончите продолжительный отдых или не израсходуете ячейку заклинания 2-го уровня или выше, чтобы применить это умение снова. У вас может быть только один предмет, созданный этим умением, одновременно: если вы используете это действие снова, то предыдущий предмет немедленно исчезает. Максимально возможный размер предмета, который вы можете создать с помощью этого умения, увеличивается на одну категорию, когда вы достигаете 6-го уровня (Большой) и 14-го уровня (Огромный)."}]},"subprev:Варвар:Путь берсерка":{"title":"Путь берсерка","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Бешенство"},{"p":"Находясь в состоянии ярости, вы можете впасть в бешенство. В этом случае, пока ваша ярость не прекратилась, вы можете в каждый свой ход после текущего совершать бонусным действием одну рукопашную атаку оружием. После окончания ярости вы получаете одну степень истощения."}]},"subprev:Варвар:Путь тотемного воина":{"title":"Путь тотемного воина","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Искатель духов"},{"p":"Ваш путь, тесно связанный с дикой природой, даёт вам близость с животными. Вы получаете возможность накладывать заклинания животные чувства и разговор с животными, но только в виде ритуалов."},{"h":"Тотемный дух"},{"p":"Вы выбираете своего тотемного духа и получаете его умения. Вы должны сделать или приобрести тотем: физический предмет (амулет или похожее украшение), содержащий мех или кожу, перья, когти, зубы или кости тотемного животного. Если хотите, можете приобрести незначительные физические изменения, напоминающие ваше тотемное животное. Например, если вашим тотемным животным является медведь, вы можете получить необычную волосатость и толстокожесть, а если это орёл, то ваши глаза могут приобрести ярко-жёлтый цвет. Ваше тотемное животное должно относиться к одному из перечисленных ниже, но быть естественным для вашей родной местности. Например, вместо орла может быть ястреб или гриф."},{"p":"Волк. Пока вы находитесь в состоянии ярости, ваши друзья совершают броски рукопашных атак по всем враждебным вам существам, находящимся в пределах 5 футов от вас, с преимуществом. Дух волка делает вас вожаком стаи."},{"p":"Медведь. В состоянии ярости вы получаете сопротивление урону всех видов, кроме урона психической энергией. Дух медведя делает вас достаточно крепким, чтобы выдержать любое испытание."},{"p":"Орёл. Когда вы находитесь в состоянии ярости и не носите тяжёлых доспехов, другие существа совершают провоцированные атаки по вам с помехой. В свой ход вы можете совершать Рывок бонусным действием. Дух орла превращает вас в хищника, с лёгкостью носящегося по полю боя."},{"p":"Лось (Источник: «Sword Coast Adventurer’s Guide»). Когда вы находитесь в состоянии ярости и не носите тяжёлых доспехов, ваша скорость ходьбы увеличивается на 15 футов. Дух лося делает вас необычайно подвижным."},{"p":"Тигр (Источник «Sword Coast Adventurer’s Guide»). Пока вы находитесь в ярости, вы можете добавить 10 футов к дальности вашего прыжка в длину и 3 фута к прыжку в высоту. Дух тигра помогает вам набрасываться на врагов."}]},"subprev:Варвар:Путь буревестника":{"title":"Путь буревестника","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Аура бури"},{"p":"Вы излучаете штормовую магическую ауру во время ярости. Аура распространяется от вас на 10 футов во всех направлениях, но не через полные укрытия. У вашей ауры есть эффект, который активируется когда вы входите в ярость, и вы можете активировать эффект снова в каждый свой ход бонусным действием. Выберите пустыню, море или тундру. Ваш эффект ауры зависит от выбранной среды как описано ниже. Вы можете сменить выбор окружения когда получаете уровень в этом классе. Если эффект вашей ауры требует спасброска, Сл равна 8 + ваш бонус мастерства + ваш модификатор Телосложения."},{"p":"Пустыня. Когда активируется этот эффект, все остальные существа в вашей ауре получают 2 урона огнём каждое. Урон увеличивается когда вы достигаете определенных уровней в этом классе: до 3 на 5-м уровне, 4 на 10-м уровне, 5 на 15-м уровне и 6 на 20-м уровне."},{"p":"Море. Когда активируется этот эффект, вы можете выбрать любое другое существо, которое можете видеть в пределах действия вашей ауры. Цель должна совершить спасбросок Ловкости. Цель получает 1к6 урона электричеством при провале или половину урона при успехе. Урон увеличивается когда вы достигаете определенных уровней в этом классе: до 2к6 на 10-м уровне, 3к6 на 15-м уровне, и 4к6 на 20-м уровне."},{"p":"Тундра. Когда активируется этот эффект, каждое существо по вашему выбору в пределах действия вашей ауры получает 2 временных хита, так как ледяные духи делают их менее чувствительными к страданиям. Количество временных хитов увеличивается, когда вы достигаете определенных уровней в этом классе: до 3 на 5-м уровне, 4 на 10-м уровне, 5 на 15-м уровне и 6 на 20-м уровне."}]},"subprev:Варвар:Путь предка-хранителя":{"title":"Путь предка-хранителя","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Древние защитники"},{"p":"Когда вы впадаете в ярость, появляются призрачные воины. Пока вы в ярости, первое существо, по которому вы попадаете атакой в свой ход, становится целью воинов, которые мешают его атакам."},{"p":"До начала вашего следующего хода цель совершает броски атаки, которые не направлены на вас, с помехой, а когда цель попадает атакой по существу, отличному от вас, то существо имеет сопротивление урону, наносимому атакой. Эффект на цели заканчивается раньше, если ваша ярость заканчивается."}]},"subprev:Варвар:Путь фанатика":{"title":"Путь фанатика","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Божественный гнев"},{"p":"Вы можете вкладывать божественный гнев в ваши удары оружием. Пока вы в ярости, первое существо, по которому вы попадаете атакой оружием в каждый свой ход, получает дополнительный урон, равный 1к6 + половина вашего уровня варвара."},{"p":"Вы самостоятельно выбираете тип урона при получении этого умения из урона излучением или некротической энергией."},{"h":"Воин богов"},{"p":"Ваша душа отмечена для вечной битвы. Если заклинание, такое как оживление, имеет единственный эффект — вернуть вас к жизни (но не нежитью), заклинателю не требуются материальные компоненты, чтобы наложить его на вас."}]},"subprev:Варвар:Путь дикой магии":{"title":"Путь дикой магии","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Магическая осведомлённость"},{"p":"Действием вы можете открыть свое сознание присутствию концентрированной магии. До конца вашего следующего хода вы знаете местоположение любого заклинания или магического предмета в пределах 60 футов от вас, если они не находятся за полным укрытием. Когда вы чувствуете заклинание, вы узнаете, к какой школе магии оно принадлежит."},{"p":"Вы можете использовать это умение количество раз, равное вашему бонусу мастерства. Вы восстанавливаете все потраченные использования после окончания продолжительного отдыха."},{"h":"Всплеск дикости"},{"p":"Магическая энергия, бурлящая внутри вас, иногда вырывается наружу. Когда вы впадаете в ярость, совершите бросок по таблице «Дикая магия», чтобы определить произведённый магический эффект."},{"p":"Если эффект требует спасброска, то он имеет Сл 8 + ваш бонус мастерства + ваш модификатор Телосложения."},{"h":"Дикая магия"},{"t":[["1","Вокруг вас вьются тёмные щупальца. Каждое существо по вашему выбору, которое вы можете видеть в пределах 30 футов от вас, должно преуспеть в спасброске Телосложения, иначе получит 1к12 урона некротической энергией. Вы также получаете 1к12 временных хитов."],["2","Вы телепортируетесь на расстояние до 30 футов в свободное пространство, которое вы можете видеть. Пока ваша ярость не закончится, вы можете каждый свой ход бонусным действием применять этот эффект."],["3","В пределах 5 футов от одного существа по вашему выбору, которое вы можете видеть в пределах 30 футов, появляется неосязаемый дух, выглядящий как фламф или пикси (по вашему выбору). В конце текущего хода дух взрывается, и каждое существо в пределах 5 футов от него должно преуспеть в спасброске Ловкости, иначе получит 1к6 урона силовым полем. Пока ваша ярость не закончится, вы можете каждый свой ход бонусным действием применять этот эффект, вызывая нового духа."],["4","Одно оружие в ваших руках по вашему выбору наполняет магия. Пока ваша ярость не закончится, оружие приобретает свойства «лёгкое» и «метательное» (дис. 20/60), и тип его урона изменяется на урон силовым полем. Если оружие покидает вашу руку, то оно снова появляется в вашей руке в конце этого хода."],["5","Пока ваша ярость не закончится, всякий раз, когда существо попадает по вам броском атаки, в ответ на атаку из вас выплёскивается магия, и существо получает 1к6 урона силовым полем."],["6","Пока ваша ярость не закончится, вас окружают разноцветные защитные огоньки. Вы и все ваши союзники в пределах 10 футов от вас получаете бонус +1 к КД."],["7","Вокруг вас временно вырастают цветы и лозы. Пока ваша ярость не закончится, земля в пределах 15 футов от вас является труднопроходимой местностью для ваших врагов."],["8","Из вашей груди вырывается луч света. Другое существо по вашему выбору, которое вы можете видеть в пределах 30 футов, должно преуспеть в спасброске Телосложения, иначе получит 1к6 урона излучением и станет ослеплённым до начала вашего следующего хода. Пока ваша ярость не закончится, вы можете каждый свой ход бонусным действием применять этот эффект."]],"head":["к8","Магический эффект"]}]},"subprev:Варвар:Путь зверя":{"title":"Путь зверя","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Форма зверя"},{"p":"Когда вы входите в ярость, вы можете трансформироваться, раскрывая свою внутреннюю звериную силу. Пока ярость не закончится, вы обладаете природным оружием. Для вас оно считается простым рукопашным оружием, и вы, как обычно, добавляете свой модификатор Силы к броскам атаки и урона, когда атакуете этим оружием."},{"p":"Вы выбираете форму оружия каждый раз, когда входите в ярость:"},{"p":"Укус. Ваш рот превращается в звериную пасть или большие челюсти (по вашему выбору). Этот укус наносит 1к8 колющего урона при попадании. Один раз в каждый свой ход, когда вы наносите урон существу этим укусом, вы восстанавливаете количество хитов, равное вашему бонусу мастерства, при условии, что у вас было меньше половины хитов, когда вы попали атакой."},{"p":"Когти. Каждая из ваших кистей превращается в когтистую лапу, которую вы можете использовать в качестве оружия, если она не занята. Эти когти наносят 1к6 рубящего урона при попадании. Один раз в каждый свой ход, когда вы атакуете когтями, используя действие Атака, вы можете совершить одну дополнительную атаку когтями частью того же действия."},{"p":"Хвост. У вас вырастает хлёсткий, колючий хвост, который наносит 1к8 колющего урона при попадании и обладает свойством «досягаемость». Если существо, которое вы видите в пределах 10 футов от вас, попадает по вам броском атаки, вы можете реакцией взмахнуть хвостом и совершить бросок к8, увеличив ваш КД на выпавшее значение, потенциально заставляя атаку промахнуться."},{"p":"Описание оружия Хвоста может запутать. В описании говорится о том, что КД от хвоста повышается, без дополнительных уточнений. Но подразумевается, что увеличение применяется только на одну атаку, которая и спровоцировала реакцию."}]},"subprev:Воин:Мастер боевых искусств":{"title":"Мастер боевых искусств","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Боевое превосходство"},{"p":"Если вы выбираете этот архетип, вы изучаете приёмы, использующие специальные кости, называемые костями превосходства."},{"p":"Приёмы. Вы изучаете три приёма на ваш выбор. Большинство приёмов тем или иным образом усиливают атаку. Во время одной атаки вы можете использовать только один приём. Вы изучаете два дополнительных приёма при достижении 7-го, 10-го и 15-го уровней. Каждый раз, при изучении новых приёмов, вы можете также заменить один из известных вам приёмов на другой."},{"p":"Кости превосходства. У вас есть четыре кости превосходства. Это кости к8. Кости превосходства тратятся при использовании. Вы восполняете все потраченные кости в конце короткого или продолжительного отдыха."},{"p":"Вы получаете ещё по одной кости превосходства на 7-м и 15-м уровнях."},{"p":"Спасброски. Некоторые из ваших приёмов требуют от цели спасброска, чтобы избежать эффекта приёма. Сложность такого спасброска рассчитывается следующим образом:"},{"p":"Сложность спасброска приёма = 8 + ваш бонус мастерства + ваш модификатор Силы или Ловкости (на ваш выбор)"},{"h":"Ученик войны"},{"p":"Вы осваиваете владение одним из ремесленных инструментов на ваш выбор."}]},"subprev:Воин:Мистический рыцарь":{"title":"Мистический рыцарь","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Использование заклинаний"},{"p":"К своим воинским талантам вы добавляете возможность накладывать заклинания. Смотрите общие правила о заклинаниях и список заклинаний волшебника."},{"p":"Заговоры. Вы изучаете 2 заговора на свой выбор из списка заклинаний волшебника. Дополнительный заговор волшебника вы изучите на 10-м уровне."},{"p":"Ячейки заклинаний. Таблица заклинаний мистического рыцаря содержит информацию о количестве доступных вам ячеек заклинаний для накладывания заклинаний волшебника. Чтобы накладывать заклинание волшебника определённого уровня, вы должны потратить ячейку того же уровня или выше. Все потраченные ячейки заклинаний вы восстанавливаете после окончания продолжительного отдыха."},{"p":"Например, если вы знаете заклинание 1-го уровня щит и имеете ячейки 1-го и 2-го уровней, вы можете наложить это заклинание, использовав любую из этих ячеек."},{"p":"Известные заклинания первого и более высоких уровней. Вы знаете три заклинания 1-го уровня из списка волшебника на свой выбор, два из которых должны принадлежать к школам Воплощения и Ограждения."},{"p":"Колонка «известные заклинания» в таблице показывает, когда вы сможете выучить новые заклинания волшебника. Все эти заклинания должны принадлежать школам Воплощения или Ограждения, и не должны превышать уровень доступных вам ячеек заклинаний. Например, при достижении 7 уровня в этом классе вы можете выучить новое заклинание 1-го или 2-го уровня."},{"p":"Заклинания, которые вы выучите на 8-м, 14-м и 20-м уровнях, могут принадлежать любой школе магии."},{"p":"Каждый раз, получая уровень в этом классе, вы можете заменить одно из заклинаний волшебника, известное вам, другим по вашему выбору. Новое заклинание должно быть из списка доступных волшебнику, у вас должны быть ячейки соответствующего уровня, и заклинание должно принадлежать школам Воплощения или Ограждения, кроме случаев, когда вы заменяете заклинания, полученные из любой школы на 3-м, 8-м, 14-м или 20-м уровнях."},{"p":"Базовая характеристика заклинаний. Интеллект является базовой характеристикой для ваших заклинаний, поскольку вы узнаёте заклинания посредством изучения и запоминания. Когда заклинание требует использовать базовую характеристику, вы используете Интеллект. Кроме того, вы используете модификатор Интеллекта при определении Сл спасбросков от ваших заклинаний волшебника и при броске атаки заклинаниями."},{"p":"Сл спасброска = 8 + ваш бонус мастерства + ваш модификатор Интеллекта"},{"p":"Модификатор броска атаки = ваш бонус мастерства + ваш модификатор Интеллекта"},{"h":"Связь с оружием"},{"p":"Вы узнаёте ритуал, позволяющий создать магическую связь между вами и одним оружием. Вы выполняете ритуал в течение 1 часа, и он может быть совершён в течение короткого отдыха. Оружие во время проведения ритуала должно находиться на доступном расстоянии от вас, и в конце вы должны прикоснуться к нему и создать связь."},{"p":"Как только вы привязали к себе оружие, вы не можете быть обезоруженным, пока не станете недееспособным. Если оружие находится на одном плане существования с вами, вы можете в свой ход бонусным действием призвать его, телепортируя себе в руку."},{"p":"У вас может быть не более двух привязанных оружий одновременно, и бонусным действием вы призываете их по одному. Если вы попытаетесь создать связь с третьим оружием, вам придётся разорвать связь с одним из первых двух."}]},"subprev:Воин:Чемпион":{"title":"Чемпион","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Улучшенные критические попадания"},{"p":"Ваши атаки оружием совершают критическое попадание при выпадении «19» или «20» на кости атаки."}]},"subprev:Воин:Кавалерист":{"title":"Кавалерист","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Дополнительные владения"},{"p":"Вы получаете владение одним из следующих навыков по вашему выбору: Выступление, История, Проницательность, Убеждение или Уход за животными."},{"p":"В качестве альтернативы вы можете выучить один язык по вашему выбору."},{"h":"Непоколебимая метка"},{"p":"Вы можете угрожать врагам, мешая их атакам и наказывая их за вред другим. Когда вы попадаете по существу рукопашной атакой оружием, вы можете пометить это существо до конца вашего следующего хода."},{"p":"Эффект метки заканчивается, если вы становитесь недееспособным или умираете, или же если кто-то еще отметит эту цель. Пока отмеченное существо находится в пределах 5 футов от вас, оно совершает с помехой броски атак, целью которых не являетесь вы."},{"p":"Кроме того, если отмеченное существо наносит урон кому угодно, кроме вас, вы можете совершить особую рукопашную атаку оружием против помеченного существа бонусным действием в свой следующий ход."},{"p":"Эту атаку вы совершаете с преимуществом, при попадании нанося дополнительный урон, равный половине вашего уровня воина."},{"p":"Независимо от количества существ, которых вы отметили, вы можете совершить эту специальную атаку количество раз, равное модификатору вашей Силы (минимум один), и восстанавливаете все потраченные атаки, после окончания продолжительного отдыха."},{"h":"Рожденный в седле"},{"p":"Ваше мастерство всадника становится очевидным. Вы совершаете с преимуществом спасброски, чтобы избежать падения с вашего скакуна."},{"p":"Если вы падаете со скакуна и приземляетесь в пределах 10 футов, то вы приземляетесь на ноги, если не становитесь недееспособным."},{"p":"И наконец, забраться в седло и спешиться стоит вам всего 5 футов передвижения, а не половину скорости."}]},"subprev:Воин:Мистический лучник":{"title":"Мистический лучник","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Знания мистического лучника"},{"p":"Вы учите некоторые природные секреты и магическую теорию – типичные для практиков этой военной эльфийской традиции. Вы получаете владение, по вашему выбору, навыком Магия или Природа, а также учите заговор фокусы или искусство друидов ."},{"h":"Магический выстрел"},{"p":"Вы учитесь высвобождать особые магические эффекты вместе с некоторыми своими выстрелами в бою. Когда вы получаете это умение, вы учите два варианта магического выстрела по своему выбору (см. «Варианты Магического выстрела» ниже)."},{"p":"Раз в ход, когда вы выпускаете стрелу из своего короткого или длинного лука в качестве части действия Атака, вы можете применить один из своих вариантов магического выстрела к этой стреле."},{"p":"Вы решаете, применять ли эту способность, после успешного попадания стрелой в существо, кроме случаев, когда выбранный вариант не требует броска атаки."},{"p":"У вас есть два использования этой способности, и вы восстанавливаете все потраченные использования после окончания короткого или продолжительного отдыха."},{"p":"Вы выбираете дополнительный вариант магического выстрела, когда достигаете определенных уровней в этом классе: 7-го, 10-го, 15-го, 18-го."},{"p":"Каждый вариант улучшается, когда вы становитесь воином 18-го уровня."}]},"subprev:Воин:Самурай":{"title":"Самурай","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Дополнительные владения"},{"p":"Вы получаете владение одним из следующих навыков по вашему выбору: Выступление, История, Проницательность или Убеждение. В качестве альтернативы вы можете выучить один язык по вашему выбору."},{"h":"Боевой дух"},{"p":"Ваша стремительность в битве может помочь вам защититься и нанести точный удар."},{"p":"Бонусным действием на своём ходу вы можете дать себе преимущество на броски атаки оружием до конца текущего хода. При этом вы также получаете 5 временных хитов. Количество временных хитов увеличивается, когда вы достигаете определённых уровней в этом классе: 10 на 10-м уровне и 15 на 15-м уровне."},{"p":"Вы можете использовать это умение три раза. Вы восстанавливаете все потраченные использования после окончания продолжительного отдыха."}]},"subprev:Воин:Пси-воин":{"title":"Пси-воин","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Псионическая сила"},{"p":"В вас скрыт источник псионической энергии. Эта псионическая энергия представляется в виде костей псионической энергии к6. Количество имеющихся у вас костей псионической энергии равно вашему удвоенному бонусу мастерства. Эти кости питают ваши псионические силы, которые подробно описаны ниже."},{"p":"Некоторые из ваших сил расходуют кости псионической энергии так, как указано в описании способности. Вы не можете использовать способности, если все ваши кости псионической энергии израсходованы. Вы восстанавливаете все израсходованные кости псионической энергии, когда заканчиваете продолжительный отдых. Кроме того, бонусным действием вы можете восстановить себе одну израсходованную кость псионической энергии, но не можете сделать это снова, пока не закончите короткий или продолжительный отдых."},{"p":"Тип вашей кости псионической энергии меняется по мере роста уровня в этом классе: на 5-м уровне (к8), 11-м уровне (к10) и 17-м уровне (к12)."},{"p":"Ваши кости псионической энергии расходуются на следующие способности:"},{"p":"Защитное поле. Когда вы или другое существо, которое вы можете видеть в пределах 30 футов, получаете урон, вы можете реакцией потратить кость псионической энергии и совершить её бросок, уменьшив получаемый урон на количество, равное результату броска кости + ваш модификатор Интеллекта (минимум 1), так как вы мгновенно создаете щит из телекинетической силы."},{"p":"Псионический удар. Вы можете наделить своё оружие псионической силой. Один раз в каждый свой ход, сразу же после попадания атакой оружием и нанесения урона цели, находящейся в пределах 30 футов от вас, вы можете потратить кость псионической энергии и совершить её бросок, нанеся дополнительный урон силовым полем по той же цели, в количестве, равном результату броска кости псионической энергии + ваш модификатор Интеллекта."},{"p":"Телекинетическое передвижение. Вы можете передвинуть объект или существо при помощи силы разума. Действием вы нацеливаетесь на свободный объект Большого размера или меньше либо на одно согласное существо, отличное от вас. Если вы можете видеть цель и она находится в пределах 30 футов от вас, вы можете передвинуть её на расстояние до 30 футов в свободное пространство, которое вы можете видеть. В качестве альтернативы, если это Крошечный объект, вы можете переместить его к себе в руку или из своей руки. В любом случае вы можете перемещать объект горизонтально, вертикально или по обеим осям. Когда вы используете действие подобным образом, вы не сможете сделать это вновь, пока не закончите короткий или продолжительный отдых или не потратите кость псионической энергии на повторное использование этого умения."}]},"subprev:Воин:Рунный рыцарь":{"title":"Рунный рыцарь","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Бонусные владения"},{"p":"Вы получаете владение инструментами кузнеца, а также учитесь писать, читать и говорить на Великаньем языке."},{"h":"Резчик рун"},{"p":"Вы можете использовать магические руны для улучшения вашего снаряжения. Вы изучаете две руны по вашему выбору из числа рун, описанных ниже, и каждый раз, когда вы получаете уровень в этом классе, вы можете заменить одну известную вам руну другой из описанных в этом умении. Когда вы достигнете определённых уровней в этом классе, вы узнаете дополнительные руны, как показано в таблице «Известные руны»."},{"h":"Известные руны"},{"t":[["3","2"],["7","3"],["10","4"],["15","5"]],"head":["Уровень воина","Количество рун"]},{"p":"Каждый раз, когда вы заканчиваете продолжительный отдых, вы можете прикоснуться к количеству предметов, равному количеству известных вам рун, и нанести различные руны на каждый из этих предметов. Чтобы вы могли сделать это, предмет должен быть оружием, доспехом, щитом, украшением или чем-то еще, что вы можете носить или держать в руке. Ваша руна остаётся на предмете до тех пор, пока вы не закончите продолжительный отдых. Один предмет может иметь только одну начерченную на нём руну."},{"p":"Перечисленные далее руны становятся вам доступны, когда вы их изучаете. Если руна имеет требование к уровню, то вы должны иметь соответствующий уровень в этом классе, чтобы изучить её. Если руна требует спасброска, то:"},{"p":"Сл спасброска вашей рунной магии = 8 + ваш бонус мастерства + ваш модификатор Телосложения"},{"p":"Каменная руна. Эта руна воплощает рассудительность каменных великанов. Пока вы несёте или носите предмет с этой руной, вы совершаете с преимуществом проверки Мудрости (Проницательность), и получаете тёмное зрение на 120 футов."},{"p":"Кроме того, когда существо, которое вы можете видеть, оканчивает свой ход в пределах 30 футов от вас, реакцией вы можете пробудить силу руны и заставить его совершить спасбросок Мудрости. При провале оно становится очарованным вами на 1 минуту. Пока оно очаровано таким способом, его скорость равна 0, и оно считается недееспособным, оказываясь в магическом ступоре. Существо может повторять спасбросок в конце каждого своего хода, оканчивая на себе эффект при успехе. Единожды пробудив руну, вы больше не сможете сделать этого до окончания короткого или продолжительного отдыха."},{"p":"Ледяная руна. Магия этой руны взывает к силам существ, выживающих в заснеженных пустошах, — таких, как ледяные великаны. Пока вы несёте или носите предмет с этой руной, вы совершаете с преимуществом проверки Мудрости (Уход за животными) и Харизмы (Запугивание)."},{"p":"Кроме того, вы можете бонусным действием пробудить силу руны, увеличив свою стойкость. В течение 10 минут вы получаете бонус +2 ко всем проверкам характеристик и спасброскам, использующим Силу или Телосложение. Единожды пробудив руну, вы больше не сможете сделать этого до окончания короткого или продолжительного отдыха."},{"p":"Облачная руна. Магия этой руны воплощает обманчивость облачных великанов. Пока вы несёте или носите предмет с этой руной, вы совершаете с преимуществом проверки Ловкости (Ловкость рук) и Харизмы (Обман)."},{"p":"Кроме того, когда атака попадает по вам или по существу, которое вы можете видеть в пределах 30 футов, вы можете реакцией пробудить силу руны, изменяя цель атаки на любое существо в пределах 30 футов от вас (кроме атакующего). Выбранное существо становится целью этой атаки с тем же броском атаки. Эта магия может передавать атакующие эффекты вне зависимости от дальности атаки. Единожды пробудив руну, вы больше не сможете сделать этого до окончания короткого или продолжительного отдыха."},{"p":"Огненная руна. Магия этой руны воплощает в себе мастерство изготовления предметов великими кузнецами. Пока вы несёте или носите предмет с этой руной, ваш бонус мастерства удваивается для любых проверок характеристик с применением инструментов, которыми вы владеете."},{"p":"Кроме того, когда вы попадаете по существу атакой оружием, вы можете пробудить руну, призвав огненные кандалы. Цель дополнительно получает 2к6 урона огнём и должна преуспеть в спасброске Силы, иначе станет опутанной на 1 минуту. Пока цель опутана таким образом, она получает 2к6 урона огнём в начале каждого своего хода. Цель может повторять спасбросок в конце каждого своего хода, уничтожая кандалы при успехе. Единожды пробудив руну, вы больше не сможете сделать этого до окончания короткого или продолжительного отдыха."},{"p":"Холмовая руна (7-й уровень или выше). Эта руна обладает магией, способной даровать устойчивость холмовых великанов. Пока вы несёте или носите предмет с этой руной, вы совершаете с преимуществом спасброски против отравления, а также получаете сопротивление урону ядом."},{"p":"Кроме того, бонусным действием вы можете пробудить силу руны, получая сопротивление дробящему, рубящему и колющему урону на 1 минуту. Единожды пробудив руну, вы больше не сможете сделать этого до окончания короткого или продолжительного отдыха."},{"p":"Штормовая руна (7-й уровень или выше). Эта руна дарует вам способность заглядывать в будущее подобно штормовым великанам. Пока вы несёте или носите предмет с этой руной, вы совершаете с преимуществом проверки Интеллекта (Магия), а также вас нельзя застать врасплох, если вы не недееспособны."},{"p":"Кроме того, бонусным действием вы можете пробудить силу этой руны и войти в пророческое состояние на 1 минуту или до тех пор, пока не станете недееспособны. Пока вы находитесь в этом состоянии, каждый раз, когда вы или любое другое существо в пределах 60 футов от вас совершаете бросок атаки, спасбросок или проверку характеристики, вы можете реакцией дать этому броску преимущество или помеху. Единожды пробудив руну, вы больше не сможете сделать этого до окончания короткого или продолжительного отдыха."},{"h":"Мощь великана"},{"p":"Вы научились наполнять себя могуществом великанов. Бонусным действием вы магическим образом можете получить следующие преимущества на 1 минуту:"},{"p":"Если ваш размер меньше, чем Большой, то вы становитесь Большим вместе со всем, что вы носите. Если вам не хватает места для увеличения, то ваш размер не меняется."},{"p":"Вы совершаете с преимуществом любые проверки Силы и спасброски Силы."},{"p":"Один раз в каждый ваш ход одна из ваших атак оружием или безоружным ударом может нанести дополнительно 1к6 урона цели при попадании."},{"p":"Вы можете использовать это умение количество раз, равное вашему бонусу мастерства. Вы восстанавливаете все потраченные использования после окончания продолжительного отдыха."}]},"subprev:Волшебник:Школа Воплощения":{"title":"Школа Воплощения","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Мастер воплощения"},{"p":"Золото и время, которое вы тратите на копирование заклинания школы Воплощения в свою книгу заклинаний, уменьшаются вдвое."},{"h":"Построение заклинаний"},{"p":"Когда вы накладываете разрушительное заклинание, то можете создать относительно безопасные участки внутри зоны поражения, которые оно не затрагивает. При накладывании заклинания школы Воплощения, воздействующего на других существ, которых вы видите, вы можете выбрать количество существ, равное 1 + уровень заклинания. Выбранные существа автоматически преуспевают в спасбросках от этого заклинания и не получают урона, если по описанию должны получить половину урона от заклинания при успешном спасброске."}]},"subprev:Волшебник:Школа Вызова":{"title":"Школа Вызова","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Мастер созидания"},{"p":"Золото и время, которое вы тратите на копирование заклинания школы Вызова в свою книгу заклинаний, уменьшаются вдвое."},{"h":"Малый вызов"},{"p":"Вы можете действием создать неодушевлённый предмет в своей руке или на земле в свободном пространстве, которое вы можете видеть, и которое расположено в пределах 10 футов от вас. Этот предмет не должен превышать в длину 3 фута (90 сантиметров) и весить более 10 фунтов, и его форма должна быть как у немагического предмета, который вы уже видели. Видно, что предмет магический, и он излучает тусклый свет в пределах 5 футов."},{"p":"Предмет исчезает через 1 час, когда вы используете это умение вновь, или когда он получает или наносит любой урон."}]},"subprev:Волшебник:Школа Иллюзии":{"title":"Школа Иллюзии","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Мастер иллюзий"},{"p":"Золото и время, которое вы тратите на копирование заклинания школы Иллюзии в свою книгу заклинаний, уменьшаются вдвое."},{"h":"Улучшенная малая иллюзия"},{"p":"Вы узнаёте заговор малая иллюзия. Если вам уже известен этот заговор, то вы изучаете любой другой заговор волшебника на свой выбор. Этот заговор не учитывается в общем количестве известных вам заговоров."},{"p":"При накладывании заклинания малая иллюзия вы можете использовать эффекты звука и изображения вместе единым заклинанием."}]},"subprev:Волшебник:Школа Некромантии":{"title":"Школа Некромантии","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Мастер некромантии"},{"p":"Золото и время, которое вы тратите на копирование заклинания школы Некромантии в свою книгу заклинаний, уменьшаются вдвое."},{"h":"Мрачная жатва"},{"p":"Вы получаете возможность собирать жизненные силы существ, которых вы убиваете своими заклинаниями. Один раз за ход, когда вы убиваете одно или несколько существ заклинанием 1-го и более высокого уровня, вы восстанавливаете хиты в количестве, равном удвоенному уровню этого заклинания, или утроенному, если заклинание принадлежало школе Некромантии. Вы не получаете это преимущество, убивая Конструктов и Нежить."}]},"subprev:Волшебник:Школа Ограждения":{"title":"Школа Ограждения","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Мастер ограждения"},{"p":"Золото и время, которое вы тратите на копирование заклинания школы Ограждения в свою книгу заклинаний, уменьшаются вдвое."},{"h":"Магическая защита"},{"p":"Вы можете плести вокруг себя магию для защиты. Когда вы накладываете заклинание школы Ограждения 1-го уровня или выше, вы можете одновременно с этим использовать прядь магии для создания магической защиты, существующей до окончания продолжительного отдыха. Защита имеет максимальные хиты, равные вашему удвоенному уровню волшебника + модификатор Интеллекта. Когда вы получаете урон, его вместо вас получает защита. Если урон опускает хиты защиты до 0, то оставшийся после этого урон получаете вы. Когда у защиты остаётся 0 хитов, она не может поглощать урон, но её магия остаётся. Если вы накладываете заклинание школы Ограждения 1-го уровня или выше, защита восстанавливает количество хитов, равное удвоенному уровню заклинания. Единожды создав защиту, вы не можете создать её вновь, пока не закончите продолжительный отдых."}]},"subprev:Волшебник:Школа Очарования":{"title":"Школа Очарования","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Мастер очарования"},{"p":"Золото и время, которое вы тратите на копирование заклинания школы Очарования в свою книгу заклинаний, уменьшаются вдвое."},{"h":"Гипнотический взгляд"},{"p":"Ваши тихие слова и завораживающий взгляд волшебным образом могут одурманить другое существо. Выберите действием одно видимое вами существо в пределах 5 футов от себя. Если цель может видеть или слышать вас, она должна преуспеть в спасброске Мудрости против Сл вашего заклинания волшебника, иначе она будет очарована вами до конца вашего следующего хода. Скорость очарованного существа падает до 0, оно недееспособно и выглядит потрясённым. В следующие ходы вы можете действием поддерживать этот эффект, продлевая его до конца своего следующего хода. Однако эффект прекращается, если вы удалитесь от существа более чем на 5 футов, если существо не может больше ни видеть, ни слышать вас, или если существо получает урон."},{"p":"После окончания эффекта, или если существо успешно совершило спасбросок от него, вы не можете использовать данное умение против этого существа, пока не закончите продолжительный отдых."}]},"subprev:Волшебник:Школа Преобразования":{"title":"Школа Преобразования","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Мастер преобразования"},{"p":"Золото и время, которое вы тратите на копирование заклинания школы Преобразования в свою книгу заклинаний, уменьшаются вдвое."},{"h":"Малая алхимия"},{"p":"Вы можете временно изменять физические свойства одного немагического предмета, превращая структуру вещества из одной в другую. Вы совершаете специальную алхимическую процедуру на одном предмете, состоящем полностью из дерева, камня (но не драгоценного камня), железа, меди или серебра, превращая его в один из этих материалов. За каждые 10 минут вы можете преобразовать до 1 кубического фута материала. Через 1 час, или когда вы теряете концентрацию (как если бы вы концентрировались на заклинании), материал возвратится в своё первоначальное состояние."}]},"subprev:Волшебник:Школа Прорицания":{"title":"Школа Прорицания","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Мастер прорицания"},{"p":"Золото и время, которое вы тратите на копирование заклинания школы Прорицания в свою книгу заклинаний, уменьшаются вдвое."},{"h":"Знамение"},{"p":"Когда вы выбираете эту школу, в вашем сознании возникают проблески будущего. Когда вы заканчиваете продолжительный отдых, сделайте два броска к20 и запишите их результаты. Вы можете заменить любой бросок атаки, спасбросок, или проверку характеристики, совершенную вами или существом, которое вы можете видеть, одним из этих бросков предсказания. Вы должны сделать выбор о том, что так поступаете, до броска, и вы можете заменить значение броска подобным путём только один раз за ход."},{"p":"Каждый бросок предсказания может быть использован только один раз. Когда вы заканчиваете продолжительный отдых, вы теряете все неиспользованные броски предсказания."}]},"subprev:Волшебник:Военная магия":{"title":"Военная магия","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Магическое отражение"},{"p":"Вы обучаетесь тому, как плести магию так, чтобы укрепить своё сопротивление всякому вреду."},{"p":"Когда по вам попадает атака или вы проваливаете спасбросок, вы можете реакцией получить бонус +2 к КД от этой атаки или бонус +4 к этому спасброску."},{"p":"Когда вы использовали это умение, вы не можете накладывать никаких заклинаний, кроме заговоров до конца своего следующего хода."},{"h":"Тактическая смекалка"},{"p":"Ваша способность оценивать тактические ситуации позволяет вам действовать быстрее в бою. Вы можете получить бонус к броску инициативы равный вашему модификатору Интеллекта."}]},"subprev:Волшебник:Орден писцов":{"title":"Орден писцов","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Волшебное перо"},{"p":"Бонусным действием вы можете магическим образом создать Крошечное перо в своей свободной руке. Это перо обладает следующими свойствами:"},{"p":"Перо не требует чернил. Когда вы пишете им, перо само создает чернила выбранного вами цвета на поверхности письма."},{"p":"Время, которое вы должны потратить, чтобы скопировать заклинание в свою книгу заклинаний, равно 2 минутам за каждый уровень заклинания, если вы используете это перо для записи заклинания."},{"p":"Вы можете стереть всё, что вы писали этим пером, если вы взмахнёте пером над текстом, потратив бонусное действие, при условии, что текст находится в пределах 5 футов от вас."},{"p":"Это перо исчезает, если вы используете это умение повторно или умираете."},{"h":"Пробуждённая книга заклинаний"},{"p":"Используя специально подготовленные чернила вместе с древними практиками, передающимися в ордене, вы пробуждаете в своей книге заклинаний магическое сознание."},{"p":"Пока вы держите в руках эту книгу, она даёт вам следующие преимущества:"},{"p":"Вы можете использовать свою книгу в качестве магической фокусировки для ваших заклинаний волшебника."},{"p":"Когда вы накладываете заклинание волшебника, используя ячейку заклинания, вы можете временно изменить вид урона этого заклинания на вид урона другого заклинания, которое имеется в вашей книге заклинаний, так как сама книга магическим образом изменяет формулу заклинания. Второе заклинание должно быть того же уровня, что и ячейка заклинания, которую вы используете."},{"p":"Когда вы накладываете заклинание волшебника в качестве ритуала, вы можете использовать нормальное время накладывания заклинания, не добавляя 10 минут. Использовав это умение, вы не сможете применить его повторно пока не окончите продолжительный отдых."},{"p":"При необходимости вы можете заменить книгу во время короткого отдыха, используя волшебное перо для рисования магической печати на пустой книге или магической книге заклинаний, на которую вы настроены. По окончании отдыха сознание вашей книги заклинаний призывается в новую книгу, после чего оно превращает новую книгу в вашу книгу заклинаний со всеми заклинаниями в ней. Если ваша старая книга заклинаний всё ещё существует, заклинания исчезают с её страниц."}]},"subprev:Волшебник:Песнь клинка":{"title":"Песнь клинка","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Тренировка войны и песни"},{"p":"Вы получаете владение лёгкими доспехами и одним видом одноручного рукопашного оружия по вашему выбору."},{"p":"Вы также получаете владение навыком Выступление, если вы им еще не владеете."},{"h":"Песнь клинка"},{"p":"Вы можете пробуждать эльфийскую магию, называемую Песнью клинка, если не носите средних или тяжёлых доспехов и не используете щит. Песнь наделяет вас сверхъестественной скоростью, ловкостью и сосредоточенностью."},{"p":"Бонусным действием вы можете начать Песнь клинка, которая продлится 1 минуту. Она прервётся раньше, если вы окажетесь недееспособным, наденете средний или тяжёлый доспех или щит, а также если совершите атаку оружием, удерживаемым в двух руках. Вы также можете прервать песнь клинка в любой момент (действий не требуется)."},{"p":"Пока вы исполняете «Песнь клинка», вы получаете следующие преимущества:"},{"p":"Вы получаете бонус к КД, равный вашему модификатору Интеллекта (минимум +1)."},{"p":"Ваша скорость ходьбы увеличивается на 10 футов."},{"p":"Вы совершаете проверки Ловкости (Акробатика) с преимуществом."},{"p":"Вы получаете бонус к спасброскам Телосложения, совершаемым для поддержки концентрации на заклинании. Бонус равен вашему модификатору Интеллекта (минимум +1)."},{"p":"Вы можете использовать это умение количество раз, равное вашему бонусу мастерства. Вы восстанавливаете все потраченные использования после окончания продолжительного отдыха."}]},"subprev:Друид:Круг земли":{"title":"Круг земли","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Дополнительный заговор"},{"p":"Вы осваиваете один дополнительный заговор друида на свой выбор. Этот заговор не учитывается в общем количестве известных вам заговоров друида."},{"h":"Естественное восстановление"},{"p":"Единение с природой через медитацию позволяет вам частично восстановить магическую силу. Во время короткого отдыха можно восстановить потраченные ячейки заклинаний. Сумма уровней выбранных ячеек не должна превышать половину уровня друида (округляя в большую сторону), и ни одна ячейка не может быть 6-го уровня или выше. Применение этого умения восстанавливается после продолжительного отдыха."},{"p":"Например, будучи друидом 4-го уровня, вы можете восстановить два уровня ячеек заклинаний. Вы можете восстановить или ячейку 2-го уровня или две ячейки 1-го уровня."}]},"subprev:Друид:Круг луны":{"title":"Круг луны","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Боевой дикий облик"},{"p":"Вы можете использовать умение «Дикий облик» бонусным действием, а не действием."},{"p":"Кроме того, пока вы перевоплощены умением «Дикий облик», вы можете бонусным действием потратить ячейку заклинания, чтобы восстановить 1к8 хитов за каждый уровень потраченной ячейки."},{"h":"Облики круга"},{"p":"Обряды круга луны позволяют принимать облик более опасных животных. Вы можете превращаться в Зверя с показателем опасности до 1 (игнорируйте столбец «Макс. ПО» таблицы «Облик зверя»)."},{"p":"Начиная с 6-го уровня, вы можете превращаться в Зверя с показателем опасности вплоть до уровня друида, поделённого на 3 (округляя в меньшую сторону)."},{"p":"Таким образом, для вас таблица \"Облик зверя\" выглядит так:"},{"t":[["2","1","Без скорости плавания и полёта","список"],["4","1","Без скорости полёта","список"],["6","2","Без скорости полёта","список"],["8","2","-","список"],["9","3","-","список"],["12","4","-","список"],["15","5","-","список"],["18","6","-","список"]],"head":["Уровень","Макс. ПО","Ограничения","Список"]}]},"subprev:Друид:Круг пастыря":{"title":"Круг пастыря","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Речь лесов"},{"p":"Вы получаете возможность говорить с животными и многими феями. Вы научились говорить, читать и писать на Сильване."},{"p":"Кроме того, Звери могут понять вашу речь, а вы можете расшифровывать звуки и движения, которые они производят. У большинства животных недостаточно интеллекта для передачи или понимания сложных концепций, но дружелюбный Зверь может рассказать то, что он видел или слышал в недавнем прошлом."},{"p":"Эта способность не делает животных вашими друзьями, хотя вы можете совмещать её вместе с подарками, как если бы вы пытались завоевать доверие других НИП."},{"h":"Тотем духов"},{"p":"Вы можете вызывать духов природы, чтобы влиять на окружающий вас мир. Вы можете бонусным действием магическим образом вызвать бестелесный дух в точке, которую вы можете видеть в 60 футах. Дух создает ауру в радиусе 30 футов вокруг этой точки. Он не считается ни существом, ни объектом, хотя он имеет спектральный вид того существа, которое представляет. Вы можете бонусным действием перемещать дух на расстояние до 60 футов в пределах видимости. Дух существует в течение 1 минуты или пока вы не станете недееспособным. Использовав это умение, вы не можете использовать его повторно до окончания короткого или продолжительного отдыха."},{"p":"Эффект ауры духа зависит от типа духа, который вы вызываете из нижеперечисленных вариантов:"},{"p":"Дух единорога. Дух единорога дарует свою защиту окружающим. Вы и ваши союзники совершаете с преимуществом все проверки характеристик для обнаружения существ в ауре духа. Кроме того, если вы накладываете заклинание, используя ячейку заклинания, и оно восстанавливает хиты любого существа внутри или вне ауры, существа по вашему выбору, находящиеся внутри ауры, также восстанавливают хиты в количестве, равном вашему уровню друида."},{"p":"Дух медведя. Дух медведя даёт вам и вашим союзникам силу и выносливость. Каждое выбранное вами существо из тех, кто находится в области ауры в момент появления духа, получает временные хиты в количестве, равном 5 + ваш уровень друида. Кроме того, вы и ваши союзники совершаете с преимуществом проверки Силы и спасброски Силы, пока находитесь в ауре."},{"p":"Дух ястреба. Дух ястреба — непревзойдённый охотник, помогающий вам и вашим союзникам своим острым взглядом. Когда существо совершает бросок атаки по цели, находящейся в ауре духа, вы можете реакцией дать преимущество на этот бросок. Кроме того, вы и ваши союзники совершаете с преимуществом проверки Мудрости (Восприятие), пока находитесь в ауре."}]},"subprev:Друид:Круг снов":{"title":"Круг снов","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Утешение летнего двора"},{"p":"Вы принимаете в себя благословения Летнего Двора. Вы становитесь источником энергии, дарующим исцеление от увечий. У вас есть запас энергии фей представленный количеством костей к6, равным вашему уровню Друида."},{"p":"Вы можете бонусным действием выбрать одно существо, которое вы можете видеть в пределах 120 футов от вас, и потратить количество этих костей, равное половине вашего уровня друида или меньше, чтобы восстановить количество хитов, равное результату броска этих потраченных костей. Также цель получает по одному временному хиту за каждую потраченную кость."},{"p":"Вы восстанавливаете все потраченные кости после окончания продолжительного отдыха."}]},"subprev:Друид:Круг дикого огня":{"title":"Круг дикого огня","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Заклинания круга"},{"p":"Вы установили мистическую связь с духом дикого огня — первобытным существом созидания и разрушения. Ваша связь с этим существом даёт вам доступ к определённым заклинаниям, когда вы достигаете определённых уровней в этом классе, как показано в таблице «Заклинания круга дикого огня»."},{"p":"Как только вы получили доступ к любому из этих заклинаний, оно считается подготовленным и не учитывается в общем количестве заклинаний, которые вы можете подготовить. Если вы получаете доступ к заклинанию, которого нет в списке заклинаний друида, оно становится для вас заклинанием друида."},{"h":"Заклинания круга дикого огня"},{"t":[["2","лечение ран, огненные ладони"],["3","палящий луч, пылающий шар"],["5","возрождение, рост растений"],["7","аура жизни, огненный щит"],["9","множественное лечение ран, небесный огонь"]],"head":["Уровень друида","Заклинания"]},{"h":"Призыв духа дикого огня"},{"p":"Вы можете призвать первобытного духа, связанного с вашей душой. Действием вы можете потратить одно из ваших использований «Дикого облика», чтобы призвать первобытного духа вместо принятия животной формы."},{"p":"Дух появляется в свободном пространстве, которое вы можете видеть в пределах 30 футов от вас. В момент появления духа каждое существо в пределах 10 футов от него (кроме вас) должно преуспеть в спасброске Ловкости против Сл ваших заклинаний, иначе получит 2к6 урона огнём."},{"p":"Дух дружелюбен к вам и вашим союзникам, а также повинуется вашим командам. В бестиарии вы найдёте блок статистики дух дикого огня, который использует ваш бонус мастерства (БМ) в некоторых местах. Вы сами определяете внешний вид духа. Некоторые духи выглядят как гуманоидная фигура из переплетенных сучков, окутанных пламенем, а другие похожи на зверей, объятых огнём."},{"p":"В бою дух имеет такую же инициативу, как и вы, и ходит сразу же после вас. Он может перемещаться и использовать свою реакцию самостоятельно, но единственное действие, которое он может совершать в свой ход — это Уклонение, если только вы не используете своё бонусное действие, чтобы приказать ему сделать что-то другое. Это действие может быть одним из действий из его блока статистики или любым другим действием. Если вы недееспособны, то дух может использовать любое действие по своему выбору, а не только Уклонение."},{"p":"Дух дикого огня исчезает по истечении 1 часа, либо когда его хиты уменьшаются до 0, либо когда вы используете «Дикий облик» подобным образом повторно, либо когда вы умираете."}]},"subprev:Друид:Круг звёзд":{"title":"Круг звёзд","source":"dnd.su","full":[{"p":"Умения 2-го уровня:"},{"h":"Звёздная карта"},{"p":"Занимаясь изучением небес над головой, вы создали звёздную карту. Эта карта является Крошечным объектом, служащим в качестве заклинательной фокусировки для ваших заклинаний друида. Вы можете сами решить, как будет выглядеть этот объект, или можете совершить бросок по таблице «Звёздная карта»."},{"p":"Держа эту карту, вы получаете следующие преимущества:"},{"p":"Вы узнаёте заговор указание."},{"p":"Вы подготавливаете заклинание направляющий снаряд. Для вас оно считается заклинанием друида. Оно всегда считается подготовленным и не учитывается при подсчёте количества заклинаний, которые можно подготовить."},{"p":"Вы можете накладывать направляющий снаряд без использования ячеек заклинаний. Вы можете делать это количество раз, равное вашему бонусу мастерства, и восстанавливаете все потраченные использования после окончания продолжительного отдыха."},{"p":"Если вы потеряете свою звёздную карту, то вы можете провести ритуал длительностью 1 час, чтобы сделать новую. Эта церемония может быть проведена в течение короткого или продолжительного отдыха, и старая карта уничтожается после создания новой."},{"h":"Звёздная карта"},{"t":[["1","Свиток, покрытый изображениями созвездий"],["2","Каменная табличка с просверлёнными в ней небольшими отверстиями"],["3","Пятнистая шкура совомеда, украшенная рельефными метками"],["4","Атлас в обложке из чёрного дерева"],["5","Кристалл, способный проецировать образы созвездий при попадании света на его грани"],["6","Стеклянные диски с изображением созвездий"]],"head":["к6","Вид карты"]},{"h":"Звёздный облик"},{"p":"Бонусным действием вы можете потратить одно использование умения «Дикий облик», чтобы принять звёздный облик, а не облик Зверя."},{"p":"Находясь в звёздном облике, вы сохраняете все свои игровые показатели, однако ваше тело становится светящимся: ваши суставы мерцают как звёзды, и их, подобно изображениям на звёздных картах, соединяют светящиеся линии. Этот облик излучает яркий свет в пределах 10 футов и тусклый свет в пределах еще 10 футов. Этот облик активен в течение 10 минут. Он заканчивается раньше, если вы становитесь недееспособны, умираете или используете его ещё раз."},{"p":"Каждый раз, когда вы принимаете звёздный облик, выберите одно из указанных ниже созвездий, которое будет мерцать на вашем теле. Ваш выбор определяет преимущества, пока вы находитесь в звёздном облике:"},{"p":"Лучник. На вас проявляется созвездие лучника. Когда вы активируете этот облик, а также в ваши последующие ходы бонусным действием, пока он активен, вы можете совершать дальнобойные атаки заклинанием, направляя светящиеся стрелы в цель, находящуюся в пределах 60 футов от вас. При попадании цель получает урон излучением в количестве, равном 1к8 + ваш модификатор Мудрости."},{"p":"Чаша. На вас проявляется созвездие животворящего кубка. Когда вы накладываете заклинание, которое тратит ячейку заклинания и восстанавливает хиты существа, вы или другое существо в пределах 30 футов от вас можете восстановить хиты в количестве, равном 1к8 + ваш модификатор Мудрости."},{"p":"Дракон. На вас проявляется созвездие мудрого дракона. Когда вы совершаете проверку Интеллекта или Мудрости, а также когда вы совершаете спасбросок Телосложения для поддержания концентрации на заклинании, вы можете при выпадении на к20 результата «1–9» считать, что выпало «10»."}]},"subprev:Изобретатель:Алхимик":{"title":"Алхимик","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Владение инструментами"},{"h":"Вы получаете владение"},{"p":"инструментами алхимика. Если вы уже владеете этим набором инструментов, то вы получаете владение другими"},{"p":"инструментами ремесленника по вашему выбору."},{"h":"Заклинания алхимиков"},{"p":"У вас всегда есть подготовленные заклинания, которые вы получаете на определенных уровнях, согласно таблице «Заклинания алхимика». Для вас они считаются заклинаниями изобретателя, однако они не учитываются в общем количестве заклинаний, которые вы можете подготовить."},{"h":"Заклинания алхимика"},{"t":[["3","лечащее слово,"]],"head":["Уровень изобретателя","Заклинание"]},{"p":"луч болезни"},{"p":"5"},{"p":"пылающий шар,"},{"p":"Мельфова кислотная стрела"},{"p":"9"},{"p":"газообразная форма,"},{"p":"множественное лечащее слово"},{"p":"13"},{"p":"усыхание,"},{"p":"защита от смерти"},{"p":"17"},{"p":"облако смерти,"},{"p":"оживление"},{"h":"Экспериментальный эликсир"},{"p":"Всякий раз, заканчивая продолжительный отдых, вы можете волшебным образом создать экспериментальный эликсир в пустом сосуде, коснувшись его. Совершите бросок по таблице «Экспериментальный эликсир» для определения эффекта, который возникнет, когда кто-то выпьет эликсир. Действием существо может выпить эликсир или влить его в недееспособное существо."},{"p":"Вы можете действием создать дополнительный экспериментальный эликсир, потратив ячейку заклинания 1-го уровня или выше за каждый эликсир. Для этого вы действием создаёте эликсир в пустом сосуде, которого касаетесь, и самостоятельно выбираете эффект эликсира из таблицы «Экспериментальный эликсир»."},{"p":"Создание экспериментального эликсира требует наличия у вас инструментов алхимика. Любой эликсир, который вы создаёте с помощью этого умения, существует до тех пор, пока не будет выпит, или до конца вашего следующего продолжительного отдыха."},{"p":"Когда вы достигаете определенных уровней в этом классе, вы можете создавать дополнительные эликсиры в конце продолжительного отдыха: два на 6-м уровне и три на 15-м уровне. Бросок для определения эффекта каждого из эликсиров выполняется отдельно, и для каждого эликсира требуется свой собственный сосуд."},{"h":"Экспериментальный эликсир"},{"t":[["1","Лечение. Выпивший восстанавливает количество хитов, равное 2к4 + модификатор вашего Интеллекта."],["2","Стремительность. Скорость ходьбы выпившего увеличивается на 10 футов на 1 час."],["3","Устойчивость. Выпивший получает бонус +1 к КД на 10 минут."],["4","Смелость. Выпивший может один раз бросить к4 и добавлять выпавшее значение к каждому броску атаки и спасброску в течение следующей минуты."],["5","Полёт. Выпивший получает скорость полёта 10 футов на 10 минут."],["6","Трансформация. Тело выпившего трансформируется аналогично действию заклинания"]],"head":["к6","Эффект"]},{"p":"смена обличья. Выпивающий определяет трансформацию, вызываемую заклинанием, и этот эффект длится 10 минут."}]},"subprev:Изобретатель:Артиллерист":{"title":"Артиллерист","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Владение инструментами"},{"h":"Вы получаете владение"},{"p":"инструментами резчика по дереву. Если вы уже владеете этим набором инструментов, то вы получаете владение другими"},{"p":"инструментами ремесленника по вашему выбору."},{"h":"Заклинания артиллериста"},{"p":"У вас всегда есть подготовленные заклинания, которые вы получаете на определённых уровнях, согласно таблице «Заклинания артиллериста». Для вас они считаются заклинаниями изобретателя, однако они не учитываются в общем количестве заклинаний, которые вы можете подготовить."},{"h":"Заклинания артиллериста"},{"t":[["3","волна грома, щит"],["5","дребезги, палящий луч"],["9","огненный шар,"]],"head":["Уровень изобретателя","Заклинание"]},{"p":"стена ветров"},{"p":"13"},{"p":"град,"},{"p":"огненная стена"},{"p":"17"},{"p":"конус холода,"},{"p":"силовая стена"},{"h":"Мистическая пушка"},{"p":"Вы научились создавать мистическую пушку. Используя инструменты резчика по дереву или инструменты кузнеца, вы можете действием создать Маленькую или Крошечную мистическую пушку в свободном пространстве на горизонтальной поверхности в пределах 5 футов от вас. Маленькая пушка занимает своё пространство, тогда как Крошечную можно держать в одной руке."},{"p":"Создав пушку, вы не сможете сделать это снова, пока не закончите продолжительный отдых или не потратите ячейку заклинаний. Единовременно вы можете иметь только одну пушку, и, пока она существует, вы не можете создать новую."},{"p":"Пушка — это магический предмет. Независимо от размера она имеет КД 18 и количество хитов, равное вашему пятикратному уровню в классе изобретателя. Пушка имеет иммунитет к урону ядом и психической энергией. Если нужно будет совершить проверку характеристики или спасбросок, считайте все её характеристики равными 10 (+0). При накладывании на пушку заговора"},{"p":"починка она восстанавливает 2к6 хитов. Пушка исчезает, если её хиты опускаются до 0, либо спустя 1 час. Действием вы можете заставить её исчезнуть раньше."},{"p":"Когда вы создаете пушку, то определяете её внешний вид и то, есть ли у неё ноги. Также вы сами определяете какого именно она будет типа, выбирая из таблицы «Мистические пушки». В каждый ваш ход вы можете бонусным действием активировать пушку, если находитесь в пределах 60 футов от неё. Частью того же бонусного действия вы можете приказать пушке передвинуться или взобраться на высоту до 15 футов в свободное пространство при условии, что у неё есть ноги."},{"h":"Мистические пушки"},{"h":"Пушка"},{"h":"Эффект"},{"h":"Огнемёт"},{"p":"Пушка извергает поток огня в 15-футовом конусе от неё в указанном вами направлении. Каждое существо в зоне поражения должно совершить спасбросок Ловкости против Сл спасброска ваших заклинаний, получая 2к8 урона огнём при провале и половину этого урона при успехе. Огонь поджигает горючие предметы в области, которые никто не несёт и не носит."},{"h":"Силовая баллиста"},{"p":"Совершите дальнобойную атаку заклинанием, исходящую из пушки, по существу или предмету, находящемуся на расстоянии до 120 футов от пушки. При попадании цель получает 2к8 урона силовым полем, и, если цель — существо, она отталкивается на 5 футов от пушки."},{"h":"Защитник"},{"p":"Пушка испускает вспышку положительной энергии, которая даёт каждому существу по вашему выбору в пределах 10 футов от пушки и самой пушке количество временных хитов, равное 1к8 + ваш модификатор Интеллекта (минимум +1)."}]},"subprev:Изобретатель:Боевой кузнец":{"title":"Боевой кузнец","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Владение инструментами"},{"h":"Вы получаете владение"},{"p":"инструментами кузнеца. Если вы уже владеете этим набором инструментов, то вы получаете владение другими"},{"p":"инструментами ремесленника по вашему выбору."},{"h":"Заклинания боевого кузнеца"},{"p":"У вас всегда есть подготовленные заклинания, которые вы получаете на определённых уровнях, согласно таблице «Заклинания боевого кузнеца». Для вас они считаются заклинаниями изобретателя, однако не учитываются в общем количестве заклинаний, которые вы можете подготовить."},{"h":"Заклинания Боевого кузнеца"},{"t":[["3","щит,"]],"head":["Уровень изобретателя","Заклинание"]},{"p":"героизм"},{"p":"5"},{"p":"клеймящая кара,"},{"p":"охраняющая связь"},{"p":"9"},{"p":"аура живучести,"},{"p":"призыв заграждения"},{"p":"13"},{"p":"аура очищения,"},{"p":"огненный щит"},{"p":"17"},{"p":"изгоняющая кара,"},{"p":"множественное лечение ран"},{"h":"Боевая готовность"},{"p":"Ваша боевая подготовка и эксперименты с магией окупились, даровав две особенности:"},{"p":"Вы получаете владение воинским оружием."},{"p":"Когда вы атакуете магическим оружием, то можете использовать ваш модификатор Интеллекта вместо модификатора Силы или Ловкости для бросков атаки и урона."},{"h":"Стальной защитник"},{"p":"Ваше искусство позволило обзавестись спутником —"},{"p":"стальным защитником. Он дружелюбен к вам и вашим союзникам, и подчиняется вашим командам. Вы определяете внешний вид этого существа, а также то, две у него ноги или четыре — это не влияет на игровые характеристики."},{"p":"В бою стальной защитник имеет такую же инициативу, как и вы, и ходит сразу после вас. Он может перемещаться и использовать свою реакцию самостоятельно, но единственное действие, которое он может совершать в свой ход — это"},{"p":"Уклонение, если только вы не используете своё бонусное действие, чтобы приказать ему сделать что-то другое. Это действие может быть одним из тех, что описаны в его блоке статистики, или же любым другим. Если вы"},{"p":"недееспособны, то защитник может использовать любое действие по своему усмотрению, а не только"},{"p":"Уклонение."},{"h":"Если на защитника накладывается заговор"},{"p":"починка, то он восстанавливает 2к6 хитов. Если он умирает, то в течение часа вы можете действием оживить его, используя инструменты кузнеца. Вы должны находиться в 5 футах от стального защитника, и нужно будет потратить одну ячейку заклинания 1-го уровня или выше. Защитник возвращается к жизни через 1 минуту с полным количеством хитов."},{"p":"Вы можете создать нового защитника в конце продолжительного отдыха, если у вас есть инструменты кузнеца. Если у вас уже есть защитник, созданный с помощью этого умения, то он мгновенно погибает. Защитник также погибает, если вы умираете."}]},"subprev:Изобретатель:Бронник":{"title":"Бронник","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Владение инструментами"},{"p":"Вы получаете владение тяжёлыми доспехами, а также владение"},{"p":"инструментами кузнеца. Если вы уже владеете этим набором инструментов, то получаете владение другими"},{"p":"инструментами ремесленника по вашему выбору."},{"h":"Заклинания бронника"},{"p":"У вас всегда есть подготовленные заклинания, которые вы получаете на определенных уровнях, согласно таблице «Заклинания бронника». Для вас они считаются заклинаниями изобретателя, однако они не учитываются в общем количестве заклинаний, которые вы можете подготовить."},{"h":"Заклинания бронника"},{"t":[["3","волшебная стрела,"]],"head":["Уровень изобретателя","Заклинание"]},{"p":"волна грома"},{"p":"5"},{"p":"отражения,"},{"p":"дребезги"},{"p":"9"},{"p":"гипнотический узор,"},{"p":"молния"},{"p":"13"},{"p":"огненный щит,"},{"p":"высшая невидимость"},{"p":"17"},{"p":"создание прохода,"},{"p":"силовая стена"},{"p":"мистический доспех"},{"p":"Ваши опыты с металлами привели к тому, что вы сделали доспех проводником своей магии. Если у вас в руках находятся инструменты кузнеца, то действием вы можете превратить доспех, который на вас надет, в мистический."},{"p":"Пока вы облачены в этот доспех, вы получаете следующие преимущества:"},{"p":"Если обычно доспех имеет определённые требования к Силе, то для вашего мистического доспеха это не нужно."},{"p":"Вы можете использовать мистический доспех в качестве заклинательной фокусировки для ваших заклинаний изобретателя."},{"p":"Доспех соединён с вами и не может быть снят против вашей воли. Он полностью покрывает ваше тело, однако вы можете сложить шлем или развернуть его обратно бонусным действием. Доспех заменяет любые отсутствующие у вас конечности — замена функционирует идентично оригинальным частям тела."},{"p":"Действием вы можете снять или надеть доспех."},{"p":"Броня остаётся мистическим доспехом, пока вы не облачитесь в другой комплект доспехов или не умрёте."},{"h":"Модель доспеха"},{"p":"Вы можете модифицировать свой мистический доспех. Выберите одну из двух нижеописанных моделей: «страж» или «лазутчик». Модель, которую вы выбираете, даёт вам особые преимущества во время использования."},{"p":"Каждая модель обладает специальным оружием. Когда вы им атакуете, можете добавить к броскам атаки и урона свой модификатор Интеллекта вместо Силы или Ловкости."},{"p":"Вы можете изменить модель доспеха по окончании короткого или продолжительного отдыха при условии, что держите в руках инструменты кузнеца."},{"p":"Страж. Вы настраиваете свой доспех таким образом, чтобы быть в гуще сражения. Он имеет следующие особенности:"},{"p":"Громовые перчатки. Каждая из латных перчаток вашего доспеха, пока вы ничего в них не держите, считается простым рукопашным оружием и наносит 1к8 урона звуком при попадании. Существо, по которому попали перчаткой, до начала вашего следующего хода совершает броски атаки с помехой против всех целей кроме вас, так как доспех магическим образом испускает отвлекающий импульс, когда существо атакует кого-то другого."},{"p":"Защитное поле. Бонусным действием вы можете получить количество временных хитов, равное вашему уровню в этом классе, заменив ими любые временные хиты, которые у вас уже есть. Вы теряете эти временные хиты, если снимаете доспех. Вы можете использовать эту особенность количество раз, равное вашему бонусу мастерства, и восстанавливаете все использования, когда заканчиваете продолжительный отдых."},{"p":"Лазутчик. Вы настраиваете доспех для того, чтобы действовать деликатно. Он имеет следующие особенности:"},{"p":"Метатель молний. Похожий на драгоценный камень нарост появляется на одном из ваших бронированных кулаков или на груди (по вашему выбору). Он считается простым дальнобойным оружием с нормальной"},{"p":"дистанцией в 90 футов и максимальной дистанцией в 300 футов, наносящим 1к6 урона электричеством при попадании. Один раз в каждый свой ход, когда вы попадаете по существу этим оружием, вы можете дополнительно нанести ему 1к6 урона электричеством."},{"p":"Заряженные шаги. Ваша скорость ходьбы увеличивается на 5 футов."},{"p":"Заглушающее поле. Вы совершаете с преимуществом проверки Ловкости (Скрытность). Если доспех накладывает помеху на данную проверку, то преимущество и помеха отменяют друг друга, как и обычно."}]},"subprev:Монах:Путь открытой ладони":{"title":"Путь открытой ладони","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Техники открытой ладони"},{"p":"Вы получаете возможность манипулировать вражеской энергией ци, направляя свою собственную. Когда вы попадаете по существу атакой, дарованной «Шквалом ударов», вы можете наложить на цель один из следующих эффектов:"},{"p":"Цель должна преуспеть в спасброске Ловкости, иначе она сбивается с ног."},{"p":"Цель должна совершить спасбросок Силы. В случае провала вы можете толкнуть её от себя на расстояние до 15 футов."},{"p":"Цель не может совершать реакции до конца вашего следующего хода."}]},"subprev:Монах:Путь тени":{"title":"Путь тени","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Техника тени"},{"p":"Вы можете использовать свою ци, чтобы дублировать эффекты некоторых заклинаний. Вы можете действием использовать 2 очка ци, чтобы наложить бесследное передвижение, тёмное зрение, тишину или тьму, не требуя материальные компоненты. Кроме того, вы получаете заговор малая иллюзия, если вы еще не знаете его."}]},"subprev:Монах:Путь четырёх стихий":{"title":"Путь четырёх стихий","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Адепт стихий"},{"p":"Вы изучаете практики, позволяющие управлять четырьмя стихиями. Эти практики требуют использования очков ци."},{"p":"Вы знаете практику «Родство со стихией» и ещё одну по вашему выбору. Все практики описаны ниже. Вы изучаете одну дополнительную практику на 6-м, 11-м и 17-м уровнях."},{"p":"Каждый раз, когда вы изучаете новую практику, вы можете также заменить одну из ранее изученных практик другой, на свой выбор."},{"p":"Накладывание стихийных заклинаний. Некоторые стихийные практики позволяют вам накладывать заклинания. При накладывании этих заклинаний вы используете их обычное время накладывания и прочие правила, но вам не нужны материальные компоненты."},{"p":"При достижении 5-го уровня в этом классе вы можете тратить очки ци для усиления заклинаний, полученных благодаря стихийным практикам, если эти заклинания увеличивают свою эффективность с уровнем, как, например, огненные ладони. Уровень заклинания увеличивается на 1 за каждое потраченное очко ци. Например, если вы монах 5-го уровня и используете «Испепеляющий удар» для накладывания заклинания огненные ладони, вы можете потратить 3 очка ци, чтобы наложить его как заклинание 2-го уровня (базовая стоимость использования этой практики 2 очка ци, плюс еще 1)."},{"p":"Максимальное количество очков ци, которое может быть потрачено на одно заклинание, определяется вашим уровнем монаха и указано в таблице. Оно включает как базовую стоимость, так и дополнительно потраченные очки ци."},{"h":"ЗАКЛИНАНИЯ И ОЧКИ ЦИ"},{"t":[["5-8","3"],["9-12","4"],["13-16","5"],["17-20","6"]],"head":["Уровень монаха","Максимальное количество ци на заклинание"]}]},"subprev:Монах:Путь кэнсэя":{"title":"Путь кэнсэя","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Путь кэнсея"},{"p":"Ваше освоение боевых искусств ведёт вас к мастерству использования определенных видов оружия. Этот путь также включает в себя владение искусными мазками кисти в каллиграфии или живописи. Вы получаете следующие преимущества:"},{"p":"Оружие кэнсэя. Выберите два типа оружия в качестве своих оружий кэнсэя: одно рукопашное и одно дальнобойное. Любое из этих оружий может быть простым или воинским, у которого нет свойств тяжелое и особое. Также можно выбрать длинный лук. Вы получаете владение этим оружием, если у вас его нет. Оружие этих типов считаются для вас монашеским оружием. Многие черты этой традиции работают только с оружием кэнсэя. Когда вы достигаете 6-го, 11-го и 17-го уровней в этом классе, вы можете выбрать ещё один тип оружия вашим оружием кэнсэя — рукопашное или дальнобойное, учитывая критерии, приведённые выше."},{"p":"Ловкое парирование. Если вы совершаете безоружный удар частью действия Атака в свой ход и держите рукопашное оружие кэнсэя, вы можете использовать его, чтобы защититься. Вы получаете бонус +2 к КД до начала вашего следующего хода, если оружие находится в вашей руке, и вы не недееспособны."},{"p":"Выстрел кэнсэя. В свой ход вы можете бонусным действием сделать свои дальнобойные атаки оружием кэнсэя более смертоносными. В этом случае любая цель, по которой вы попали дальнобойной атакой, используя оружие кэнсэя, получает дополнительно 1к4 урона такого же типа, как у оружия. Вы сохраняете это преимущество до конца текущего хода."},{"p":"Путь кисти. Вы получаете владение инструментами каллиграфа или художника на ваш выбор."}]},"subprev:Монах:Путь пьяного мастера":{"title":"Путь пьяного мастера","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Дополнительные владения"},{"p":"Вы получаете владение навыком Выступление, если у вас его ещё нет. Ваша техника боевого искусства соединяет боевые тренировки с точностью танцора и выходками шута. Вы также получаете владение инструментами пивовара, если у вас его ещё нет."},{"h":"Техника пьяницы"},{"p":"Вы учитесь быстро поворачиваться во время использования «Шквала ударов». Когда вы используете «Шквал ударов», то получаете все преимущества от Отхода, а ваша скорость ходьбы увеличивается на 10 футов до конца этого хода."}]},"subprev:Монах:Путь солнечной души":{"title":"Путь солнечной души","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Луч сияющего солнца"},{"p":"Вы можете метать палящий заряд магического сияния. Вы получаете дальнобойную атаку заклинанием, которую вы можете использовать в качестве действия Атака."},{"p":"Эта особая атака — это дальнобойная атака заклинанием, имеющая дальность 30 футов. Вы получаете владение этой атакой и добавляете свой модификатор Ловкости к броскам атаки и урона."},{"p":"Атака наносит урон излучением, кость урона к4. Урон меняется с получением уровней монаха, как указано в столбце «боевые искусства» в таблице Монаха."},{"p":"Когда вы совершаете эту специальную атаку в свой ход действием Атака, вы можете потратить 1 очко ци, чтобы совершить ещё две подобные дополнительные атаки бонусным действием."},{"p":"Когда вы получаете умение «Дополнительная атака», эта особая атака может использоваться вместо любых из атак, которые вы совершаете в качестве части действия Атака."}]},"subprev:Монах:Путь астрального тела":{"title":"Путь астрального тела","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Руки астрального тела"},{"p":"Ваше мастерство во владении ци позволяет вам призвать частичку вашего астрального тела. Бонусным действием вы можете потратить 1 очко ци, чтобы призвать руки астрального тела. Когда вы используете это умение, каждое существо по вашему выбору, которое вы можете видеть в пределах 10 футов, должно преуспеть в спасброске Ловкости, иначе получит урон силовым полем, равный двум броскам ваших костей боевых искусств."},{"p":"В течение 10 минут эти призрачные руки парят на уровне ваших плеч или окружают ваши руки (по вашему выбору). Вы сами определяете внешний вид рук. Призрачные руки исчезают раньше, если вы становитесь недееспособны или умираете."},{"p":"Во время действия этого умения вы получаете следующие преимущества:"},{"p":"Вы можете использовать ваш модификатор Мудрости вместо модификатора Силы, когда совершаете проверки Силы или спасброски Силы."},{"p":"Вы можете использовать эти призрачные руки для совершения безоружных ударов."},{"p":"Если вы совершаете безоружные удары этими руками в свой ход, ваша досягаемость у этих атак на 5 футов больше, чем обычно."},{"p":"Когда вы совершаете безоружные удары этими руками, вы можете использовать ваш модификатор Мудрости вместо модификатора Силы или Ловкости для бросков атаки и урона; наносимый этими атаками урон — урон силовым полем."}]},"subprev:Монах:Путь милосердия":{"title":"Путь милосердия","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Орудия милосердия"},{"p":"Вы получаете владение навыками Проницательность и Медицина, а также получаете владение инструментами травника."},{"p":"Также вы получаете специальную маску, которую обычно носите при использовании умений этого архетипа. Вы самостоятельно определяете её внешний вид или выбираете его случайным образом, совершая бросок по таблице «Маски милосердия»."},{"h":"Маски милосердия"},{"t":[["1","Ворон"],["2","Абсолютно белая"],["3","Плачущий лик"],["4","Смеющийся лик"],["5","Череп"],["6","Бабочка"]],"head":["к6","Внешний вид маски"]},{"h":"Исцеляющая рука"},{"p":"Ваше мистическое прикосновение может исцелять раны. Действием вы можете потратить 1 очко ци, чтобы прикоснуться к существу и восстановить количество хитов, равное броску кости боевых искусств + ваш модификатор Мудрости."},{"p":"Когда вы используете «Шквал ударов», вы можете заменить один из безоружных ударов использованием этого умения без затраты очков ци на исцеление."},{"h":"Повреждающая рука"},{"p":"Вы используете свою энергию ци для нанесения ран. Когда вы попадаете по существу безоружным ударом, вы можете потратить 1 очко ци, чтобы нанести дополнительный урон некротической энергией, равный броску кости боевых искусств + ваш модификатор Мудрости. Вы можете использовать это умение только один раз за ход."}]},"subprev:Паладин:Клятва преданности":{"title":"Клятва преданности","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Заклинания клятвы"},{"p":"Вы получаете заклинания клятвы на указанных уровнях паладина."},{"h":"ЗАКЛИНАНИЯ КЛЯТВЫ ПРЕДАННОСТИ"},{"t":[["3","защита от зла и добра, убежище"],["5","малое восстановление, область истины"],["9","маяк надежды, рассеивание магии"],["13","свобода перемещения, страж веры"],["17","небесный огонь, общение"]],"head":["Уровень паладина","Заклинания"]},{"h":"Божественный канал"},{"p":"Когда вы даёте эту клятву, вы получаете следующие два варианта использования «Божественного канала»."},{"p":"Священное оружие. Вы можете действием наполнить одно оружие, которое вы держите, позитивной энергией, используя «Божественный канал». На протяжении 1 минуты вы добавляете свой модификатор Харизмы к броскам атаки, сделанным этим оружием (минимальный бонус +1). Также оружие испускает яркий свет в радиусе 20 футов и тусклый свет в пределах еще 20 футов. Если оружие не является волшебным, то оно считается волшебным в течение этого времени. Вы можете закончить этот эффект в свой ход частью любого другого действия. Если вы не держите или не несёте это оружие, или теряете сознание, то этот эффект заканчивается."},{"p":"Изгнать нечистого. Вы действием показываете свой священный символ и произносите слова молитвы, осуждающей Исчадия и Нежить, используя «Божественный канал». Все Исчадия и Нежить, которые могут видеть или слышать вас, находящиеся в пределах 30 футов от вас, должны совершить спасбросок Мудрости. Если они проваливают спасбросок, то изгоняются на 1 минуту или до тех пор, пока не получат урон."},{"p":"Изгнанные существа должны весь свой ход пытаться убежать от вас так далеко, как только могут, и не могут добровольно переместиться в пространство, находящееся в пределах 30 футов от вас. Также они не могут совершать реакции. Из всех действий они могут совершать только Рывок и попытки избежать эффекта, не дающего им перемещаться. Если же двигаться некуда, существа могут использовать действие Уклонение."}]},"subprev:Паладин:Клятва древних":{"title":"Клятва древних","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Заклинания клятвы"},{"p":"Вы получаете заклинания клятвы на указанных уровнях паладина."},{"h":"ЗАКЛИНАНИЯ КЛЯТВЫ ДРЕВНИХ"},{"t":[["3","опутывающий удар, разговор с животными"],["5","лунный луч, туманный шаг"],["9","защита от энергии, рост растений"],["13","град, каменная кожа"],["17","древесный путь, общение с природой"]],"head":["Уровень паладина","Заклинания"]},{"h":"Божественный канал"},{"p":"Когда вы даёте эту клятву, вы получаете следующие два варианта использования «Божественного канала»."},{"p":"Гнев природы. Вы можете использовать «Божественный канал», чтобы призвать первородные силы для опутывания врага. Вы можете действием опутать призрачными лозами существо, которое вы можете видеть, и которое находится в пределах 10 футов от вас. Это существо должно преуспеть в спасброске Силы или Ловкости (по своему выбору), иначе оно станет опутанным. Опутанное лозами существо повторяет спасбросок в конце каждого своего хода. В случае успеха оно освобождается, а лозы исчезают."},{"p":"Изгнать неверного. Вы можете использовать «Божественный канал» для произнесения древних слов, причиняющих боль Феям и Исчадиям, когда они слышат их. Вы действием демонстрируете свой священный символ и все Феи и Исчадия в пределах 30 футов от вас, слышащие вас, должны совершить спасбросок Мудрости. Провалив его, существо изгоняется на 1 минуту или пока не получит урон."},{"p":"Изгнанные существа должны весь свой ход пытаться убежать от вас так далеко, как только могут, и не могут добровольно переместиться в пространство, находящееся в пределах 30 футов от вас. Также они не могут совершать реакции. Из всех действий они могут совершать только Рывок и попытки избежать эффекта, не дающего им перемещаться. Если же двигаться некуда, существа могут использовать действие Уклонение."},{"p":"Если истинная форма существа скрыта иллюзией, изменением облика, или другим эффектом, скрывающим её, то она раскрывается, когда существо изгоняется."}]},"subprev:Паладин:Клятва мести":{"title":"Клятва мести","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Заклинания клятвы"},{"p":"Вы получаете заклинания клятвы на указанных уровнях паладина."},{"h":"ЗАКЛИНАНИЯ КЛЯТВЫ МЕСТИ"},{"t":[["3","метка охотника, порча"],["5","туманный шаг, удержание личности"],["9","защита от энергии, ускорение"],["13","изгнание, переносящая дверь"],["17","наблюдение, удержание чудовища"]],"head":["Уровень паладина","Заклинания"]},{"h":"Божественный канал"},{"p":"Когда вы даёте эту клятву, вы получаете следующие два варианта использования «Божественного канала»."},{"p":"Порицание врага. Вы действием демонстрируете свой священный символ и произносите обличающую молитву, используя «Божественный канал». Выберите одно существо в пределах 60 футов, которое можете видеть. Это существо должно совершить спасбросок Мудрости, если не обладает иммунитетом к испугу. Исчадия и Нежить совершают этот спасбросок с помехой."},{"p":"Если спасбросок провален, существо становится испуганным на 1 минуту, или пока не получит урон. Пока существо испугано, его скорость равна 0, и оно не получает никаких бонусов к скорости."},{"p":"Если спасбросок был успешен, скорость существа на 1 минуту, или пока оно не получает урон, уменьшается вдвое."},{"p":"Обет вражды. Вы можете бонусным действием произнести слова обета вражды по отношению к существу, которое вы можете видеть, и которое находится в пределах 10 футов от вас, используя «Божественный канал». В течение 1 минуты, пока его хиты не опускаются до 0, или оно не потеряет сознание, вы совершаете броски атаки по нему с преимуществом."}]},"subprev:Паладин:Клятва искупления":{"title":"Клятва искупления","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Заклинания клятвы"},{"p":"Вы получаете заклинания клятвы на указанных уровнях паладина."},{"t":[["3","убежище, усыпление"],["5","умиротворение, удержание личности"],["9","контрзаклинание, гипнотический узор"],["13","Отилюков упругий шар, каменная кожа"],["17","удержание чудовища, силовая стена"]],"head":["Уровень","Заклинание"]},{"h":"Божественный канал"},{"p":"Когда вы принимаете эту клятву, вы получаете следующие два варианта применения «Божественного канала»."},{"p":"Посол мира. Вы можете использовать своё умение «Божественный канал», чтобы наделить своё присутствие божественной силой. Бонусным действием вы даруете себе бонус +5 к проверкам Харизмы (Убеждение) на следующие 10 минут."},{"p":"Возмездие жестокости. Вы можете использовать свой «Божественный канал», чтобы дать отпор жестоким врагам. Сразу же после того, как атакующий в пределах 30 футов от вас наносит урон атакой существу, отличному от вас, вы можете реакцией заставить атакующего совершить спасбросок Мудрости. При провале атакующий получает столько урона излучением, сколько он нанёс урона. При успехе он получает половину этого урона."}]},"subprev:Паладин:Клятва покорения":{"title":"Клятва покорения","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Заклинания клятвы"},{"p":"Вы получаете заклинания клятвы на указанных уровнях паладина."},{"t":[["3","доспех Агатиса, приказ"],["5","удержание личности, божественное оружие"],["9","проклятие, ужас"],["13","подчинение зверя, каменная кожа"],["17","облако смерти, подчинение личности"]],"head":["Уровень","Заклинание"]},{"h":"Божественный канал"},{"p":"Когда вы принимаете эту клятву, вы получаете два следующих варианта применения «Божественного канала»."},{"p":"Покоряющее присутствие. Вы можете использовать ваш «Божественный канал», чтобы источать ужасающее присутствие. Действием вы можете заставить каждое существо по вашему выбору в пределах 30 футов совершить спасбросок Мудрости. При провале существо становится испуганным на 1 минуту. Испуганное существо может повторять этот спасбросок в конце каждого своего хода оканчивая этот эффект на себе при успехе."},{"p":"Направленный удар. Вы можете использовать свой «Божественный канал», чтобы наносить удары со сверхъестественной точностью. Когда вы проводите атаку, вы можете использовать свой «Божественный канал», чтобы получить бонус +10 к этому броску. Вы можете использовать это свойство уже после того, как увидите результат броска, но обязаны сделать выбор до того, как Мастер объявит о попадании или промахе атаки."}]},"subprev:Паладин:Клятва смотрителей":{"title":"Клятва смотрителей","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Заклинания клятвы"},{"p":"Вы получаете доступ к заклинаниям клятвы согласно таблице «Заклинания клятвы смотрителей». Как работают заклинания клятвы, сказано в «Книге игрока», в описании классового умения «Священная клятва»."},{"h":"Заклинания клятвы смотрителей"},{"t":[["3","обнаружение магии, сигнал тревоги"],["5","видение невидимого, лунный луч"],["9","контрзаклинание, необнаружимость"],["13","аура очищения, изгнание"],["17","наблюдение, удержание чудовища"]],"head":["Уровень паладина","Заклинание"]},{"h":"Божественный канал"},{"p":"Вы получаете следующие варианты применения «Божественного канала». Смотрите умение класса «Священная клятва», чтобы узнать, как работает «Божественный канал»."},{"p":"Воля смотрителей. Вы можете использовать «Божественный канал», чтобы усилить своё присутствие могущественной силой вашей веры. Действием вы выбираете количество существ, которых вы можете видеть в 30 футах, равное вашему модификатору Харизмы (минимум одно существо). В течение 1 минуты вы и все выбранные существа совершаете спасброски Интеллекта, Мудрости и Харизмы с преимуществом."},{"p":"Изгнание экстрапланара. Вы можете использовать свой «Божественный канал», чтобы наказывать потусторонних существ. Действием вы демонстрируете свой священный символ и все Аберрации, Исчадия, Небожители, Феи и Элементали в пределах 30 футов от вас, которые могут вас слышать, должны совершить спасбросок Мудрости. При провале существо изгоняется на 1 минуту или до тех пор, пока не получит урон."},{"p":"Изгнанные существа должны весь свой ход пытаться убежать от вас так далеко, как только могут, и не могут добровольно переместиться в пространство, находящееся в пределах 30 футах от вас. Из всех действий они могут совершать только Рывок или пытаться избежать эффекта, не дающего им перемещаться. Если же двигаться некуда, существа могут использовать Уклонение."}]},"subprev:Плут:Вор":{"title":"Вор","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Быстрые руки"},{"p":"Вы можете бонусным действием, предоставленным вашим Хитрым действием, совершить проверку Ловкости (Ловкость рук), использовать воровские инструменты, чтобы обезвредить ловушку или вскрыть замок, или же совершить действие Использование предмета."},{"h":"Форточник"},{"p":"Вы получаете возможность лазать быстрее, чем обычно; лазание больше не стоит вам дополнительного движения."},{"p":"Кроме того, когда вы совершаете прыжок с разбега, расстояние, которое вы преодолеваете, увеличивается на число футов, равное вашему модификатору Ловкости."}]},"subprev:Плут:Убийца":{"title":"Убийца","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Дополнительные владения"},{"p":"Вы получаете владение набором для грима и инструментами отравителя."},{"h":"Ликвидация"},{"p":"Вы становитесь смертоносными для врагов. Вы совершаете с преимуществом броски атаки по всем существам, которые ещё не совершали ход в этом бою. Кроме того, все попадания по существам, захваченным врасплох, являются критическими попаданиями."}]},"subprev:Плут:Мистический ловкач":{"title":"Мистический ловкач","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Использование заклинаний"},{"p":"Вы получаете способность накладывать заклинания. Правила по использованию заклинаний есть в этой статье: использование заклинаний."},{"p":"Заговоры. Вы знаете три заговора: волшебная рука и два других заговора по своему выбору из списка заклинаний волшебника. Вы узнаёте ещё один заговор волшебника на 10-м уровне."},{"p":"Ячейки заклинаний. В приведённой ниже таблице показано, сколько у вас есть ячеек заклинаний для сотворения заклинаний волшебника для накладывания заклинаний 1-го уровня и выше. Для накладывания одного из этих заклинаний вы должны потратить ячейку заклинаний с уровнем не ниже уровня заклинания. Вы восстанавливаете все потраченные ячейки заклинаний, когда заканчиваете продолжительный отдых."},{"p":"Например, если вы знаете заклинание 1-го уровня очарование личности и у вас есть ячейки заклинания 1-го и 2-го уровня, вы можете наложить это заклинание, используя любую из этих ячеек."},{"p":"Известные заклинания первого и более высоких уровней. Вы знаете три заклинания волшебника 1-го уровня по своему выбору, два из которых должны быть выбраны из школ Иллюзий или Очарования."},{"p":"Колонка «известные заклинания» показывает, когда вы сможете выучить новые заклинания волшебника 1-го уровня и выше. Все эти заклинания должны принадлежать школе Иллюзии или Очарования, и должны быть того уровня, для которого у вас есть ячейки заклинаний. Например, когда вы получите 7-й уровень в этом классе, вы можете узнать одно новое заклинание 1-го или 2-го уровня. Заклинания, которые вы узнаёте на 8-м, 14-м и 20-м уровнях могут принадлежать любой школе магии. Каждый раз, когда вы получаете уровень в этом классе, вы можете заменить одно известное заклинание волшебника другим заклинанием по своему выбору из списка заклинаний волшебника. Уровень нового заклинания не должен превышать уровень самой большой ячейки заклинаний, и оно должно принадлежать школе Иллюзий или Очарования, если только вы не заменяете заклинание, полученное на 8, 14 или 20 уровне из любой школы магии."},{"p":"Базовая характеристика заклинаний. При накладывании заклинаний волшебника вы используете Интеллект, так как вы узнаёте их с помощью специальных исследований и запоминания. Вы используете Интеллект в случаях, когда заклинание ссылается на базовую характеристику. Кроме того, вы используете модификатор Интеллекта при определении Сл спасбросков от ваших заклинаний волшебника, и при броске атаки заклинаниями."},{"p":"Сл спасброска = 8 + ваш бонус мастерства + ваш модификатор Интеллекта"},{"p":"Модификатор броска атаки = ваш бонус мастерства + ваш модификатор Интеллекта"},{"h":"Уровень"},{"p":"плута"},{"h":"Известные"},{"p":"заговоры"},{"h":"Известные"},{"p":"заклинания"},{"p":"Ячейки заклинаний на уровень заклинаний"},{"p":"1"},{"p":"2"},{"p":"3"},{"p":"4"},{"p":"1"},{"p":"-"},{"p":"-"},{"p":"-"},{"p":"-"},{"p":"-"},{"p":"-"},{"p":"2"},{"p":"-"},{"p":"-"},{"p":"-"},{"p":"-"},{"p":"-"},{"p":"-"},{"p":"3"},{"p":"3"},{"p":"3"},{"p":"2"},{"p":"-"},{"p":"-"},{"p":"-"},{"p":"4"},{"p":"3"},{"p":"4"},{"p":"3"},{"p":"-"},{"p":"-"},{"p":"-"},{"p":"5"},{"p":"3"},{"p":"4"},{"p":"3"},{"p":"-"},{"p":"-"},{"p":"-"},{"p":"6"},{"p":"3"},{"p":"4"},{"p":"3"},{"p":"-"},{"p":"-"},{"p":"-"},{"p":"7"},{"p":"3"},{"p":"5"},{"p":"4"},{"p":"2"},{"p":"-"},{"p":"-"},{"p":"8"},{"p":"3"},{"p":"6"},{"p":"4"},{"p":"2"},{"p":"-"},{"p":"-"},{"p":"9"},{"p":"3"},{"p":"6"},{"p":"4"},{"p":"2"},{"p":"-"},{"p":"-"},{"p":"10"},{"p":"4"},{"p":"7"},{"p":"4"},{"p":"3"},{"p":"-"},{"p":"-"},{"p":"11"},{"p":"4"},{"p":"8"},{"p":"4"},{"p":"3"},{"p":"-"},{"p":"-"},{"p":"12"},{"p":"4"},{"p":"8"},{"p":"4"},{"p":"3"},{"p":"-"},{"p":"-"},{"p":"13"},{"p":"4"},{"p":"9"},{"p":"4"},{"p":"3"},{"p":"2"},{"p":"-"},{"p":"14"},{"p":"4"},{"p":"10"},{"p":"4"},{"p":"3"},{"p":"2"},{"p":"-"},{"p":"15"},{"p":"4"},{"p":"10"},{"p":"4"},{"p":"3"},{"p":"2"},{"p":"-"},{"p":"16"},{"p":"4"},{"p":"11"},{"p":"4"},{"p":"3"},{"p":"3"},{"p":"-"},{"p":"17"},{"p":"4"},{"p":"11"},{"p":"4"},{"p":"3"},{"p":"3"},{"p":"-"},{"p":"18"},{"p":"4"},{"p":"11"},{"p":"4"},{"p":"3"},{"p":"3"},{"p":"-"},{"p":"19"},{"p":"4"},{"p":"12"},{"p":"4"},{"p":"3"},{"p":"3"},{"p":"1"},{"p":"20"},{"p":"4"},{"p":"13"},{"p":"4"},{"p":"3"},{"p":"3"},{"p":"1"},{"h":"Улучшенная волшебная рука"},{"p":"Когда вы накладываете заклинание волшебная рука, вы можете создать руку невидимой, и совершать ею следующие дополнительные действия:"},{"p":"Вы можете положить один предмет, удерживаемый рукой, в контейнер, носимый или несомый другим существом."},{"p":"Вы можете достать предмет из контейнера, носимого или несомого другим существом."},{"p":"Вы можете использовать воровские инструменты для вскрытия замков и обезвреживания ловушек в дистанции этого заклинания."},{"p":"Вы можете выполнить одно из этих действий, не будучи замеченным, если успешно совершите проверку Ловкости (Ловкость рук) против проверки Мудрости (Восприятие) существа."},{"p":"Кроме того, вы можете использовать бонусное действие, предоставленное умением «Хитрое действие», для управления рукой."}]},"subprev:Плут:Дуэлянт":{"title":"Дуэлянт","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Ловкое маневрирование"},{"p":"Вы узнаёте, как наносить удары и сразу же ускользать от контратаки. На протяжении вашего хода, если вы совершаете рукопашную атаку по существу, то до конца вашего хода это существо не может совершать провоцированные атаки против вас."},{"h":"Лихая удаль"},{"p":"Вы бросаетесь в бой смело и без колебаний. Вы добавляете свой модификатор Харизмы к результату броска инициативы. Кроме того, теперь для использования скрытой атаки вам не требуется совершать с преимуществом бросок атаки по существу, если оно находится в 5 футах от вас, в пределах 5 футов от вас больше нет других существ и у вас нет помехи на этот бросок. Все прочие правила для классового умения «Скрытая атака» применяются к вам как обычно."}]},"subprev:Плут:Комбинатор":{"title":"Комбинатор","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Интриган"},{"p":"Вы получаете владение набором для грима, набором для фальсификации и одним игровым набором на свой выбор. Вы также учите два языка по вашему выбору. В дополнение к этому, вы можете безошибочно подражать манере и акценту речи существа, разговор которого вы слышите как минимум одну минуту, что позволяет вам выдавать себя за носителя языка из определённой страны, если вы знаете язык."},{"h":"Мастер тактики"},{"p":"Вы можете использовать действие Помощь бонусным действием. Когда вы используете действие Помощь союзнику в атаке существа, цель этой атаки может быть в 30 футах от вас, а не в 5 футах, если цель может видеть или слышать вас."}]},"subprev:Плут:Скаут":{"title":"Скаут","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Зачинщик"},{"p":"К вам трудно подобраться во время боя. Вы можете реакцией переместиться на расстояние до половины вашей скорости, когда враг заканчивает свой ход в пределах 5 футов от вас. Это передвижение не вызывает провоцированных атак по вам."},{"h":"Выживальщик"},{"p":"Вы получаете владение навыками Природа и Выживание, если вы ещё не владеете ими."},{"p":"Ваш бонус мастерства удваивается при любых проверках характеристик, совершённых с использованием любого из этих навыков."}]},"subprev:Плут:Сыщик":{"title":"Сыщик","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Слух на обман"},{"p":"Вы вырабатываете талант подмечать ложь."},{"p":"Когда вы совершаете проверку Мудрости (Проницательность), чтобы распознать, обманывает ли существо, считайте выпавшие на к20 результаты «7» и ниже за «8»."},{"h":"Внимательный взгляд"},{"p":"Вы можете бонусным действием совершить проверку Мудрости (Восприятие) с целью заметить спрятанное существо или предмет, либо проверку Интеллекта (Расследование) с целью найти или расшифровать улики."},{"h":"Проницательный бой"},{"p":"Вы получаете способность распознать тактику врага и выработать противодействующую ей."},{"p":"Бонусным действием вы можете совершить проверку Мудрости (Проницательность) против существа, которое вы видите и которое не недееспособно, против проверки Харизмы (Обман) цели. При успехе вы можете использовать скрытую атаку против цели даже если у вас нет преимущества на бросок атаки, кроме случая, если у вас помеха на этот бросок."},{"p":"Этот эффект длится 1 минуту либо до тех пор, когда вы успешно используете это умение против другой цели."}]},"subprev:Плут:Фантом":{"title":"Фантом","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Шёпот мёртвых"},{"p":"Отголоски тех, кто умер, окутывают вас. Каждый раз, когда вы заканчиваете короткий или продолжительный отдых, призрачная сущность делится с вами знаниями, позволяя получить владение одним навыком или инструментом, которым вы ещё не владеете. Вы теряете это владение при использовании этого умения для замены владения на другое."},{"h":"Могильные вопли"},{"p":"Когда из-за вас противник оказывается на волосок от гибели, вы можете направить силу смерти и нанести урон кому-то ещё. Сразу после того, как вы нанесёте урон «Скрытой атакой» по существу в свой ход, вы можете выбрать целью второе существо, которое вы видите в пределах 30 футов от первого существа. Совершите бросок половины костей «Скрытой атаки» на вашем уровне (с округлением в большую сторону), и второе существо получит урон некротической энергией, равный выпавшему на костях значению. На мгновение вокруг него будут слышны вопли мёртвых."},{"p":"Вы можете использовать это умение количество раз, равное вашему бонусу мастерства. Вы восстанавливаете все потраченные использования после окончания продолжительного отдыха."}]},"subprev:Плут:Клинок души":{"title":"Клинок души","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Псионическая сила"},{"p":"В вас скрыт источник псионической энергии. Эта псионическая энергия представляется в виде костей псионической энергии к6. Количество имеющихся у вас костей псионической энергии равно вашему удвоенному бонусу мастерства. Эти кости питают ваши псионические силы, которые подробно описаны ниже."},{"p":"Некоторые из ваших сил расходуют кости псионической энергии так, как указано в описании силы. Вы не можете использовать способности, если все ваши кости псионической энергии израсходованы. Вы восстанавливаете все израсходованные кости псионической энергии, когда заканчиваете продолжительный отдых. Кроме того, бонусным действием вы можете восстановить себе одну израсходованную кость псионической энергии, но не можете сделать это снова, пока не закончите короткий или продолжительный отдых."},{"p":"Тип вашей кости псионической энергии меняется по мере роста уровня в этом классе: на 5-м уровне (к8), на 11-м уровне (к10) и на 17-м уровне (к12)."},{"p":"Ваши кости псионической энергии расходуются на следующие способности:"},{"p":"Пси-усиленная сноровка. Когда ваши непсионические методы подводят вас, псионические могут помочь: если вы проваливаете проверку характеристики, используя навык или инструмент, которым вы владеете, вы можете совершить бросок кости псионической энергии и добавить выпавшее значение к значению, полученному при проверке, потенциально обращая провал в успех. Вы расходуете кость только в том случае, если бросок успешен."},{"p":"Психический шёпот. Вы можете установить телепатическую связь с другими — это идеально для тихого проникновения. Действием выберите одно или нескольких существ, которых вы можете видеть — вы можете связаться с количеством существ, равном вашему бонусу мастерства или меньше, после чего бросьте кость псионической энергии. Результат броска определяет то, в течение скольких часов выбранные существа могут телепатически общаться с вами, а вы с ними. Чтобы отправлять или получать сообщения (действий не требуется), вы и другие существа должны быть на расстоянии не дальше 1 мили друг от друга."},{"p":"Существо не может использовать эту телепатию, если оно не может говорить ни на одном языке."},{"p":"Оно может оборвать телепатическую связь в любой момент (действий не требуется). Вам и существу необязательно говорить на общем языке, чтобы понимать друг друга."},{"p":"Когда вы впервые используете эту способность после окончания продолжительного отдыха, вы не расходуете кость псионической энергии. Во всех остальных случаях, когда вы используете способность, ваша кость расходуется."},{"h":"Психические клинки"},{"p":"Вы можете проявлять свои псионические силы в виде мерцающих клинков из психической энергии. Когда вы собираетесь совершить действие Атака, вы можете проявить психический клинок в своей свободной руке и совершить атаку им."},{"p":"Этот магический клинок — простое рукопашное оружие, обладающее свойствами «фехтовальное» и «метательное». Его нормальная дистанция равна 60 футам, зоны максимальной дистанции у оружия нет. При попадании оно наносит урон психической энергией, равный 1к6 + модификатор характеристики, которую вы использовали для совершения броска атаки. Клинок мгновенно исчезает после попадания или промаха по цели, а также не оставляет следов на цели, если наносит урон."},{"p":"После того, как вы атакуете этим клинком, вы можете бонусным действием совершить рукопашную или дальнобойную атаку оружием, используя второй психический клинок при условии, что у вас свободна другая рука для его создания. Кость урона этой бонусной атаки равна 1к4, а не 1к6."}]},"subprev:Следопыт:Охотник":{"title":"Охотник","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Добыча охотника"},{"p":"Вы получаете одно из следующих умений на свой выбор:"},{"p":"Сокрушитель орд. Один раз в каждый свой ход, когда вы совершаете атаку оружием, вы можете совершить еще одну атаку тем же оружием по другому существу, находящемуся в пределах 5 футов от первичной цели, и находящемуся в пределах досягаемости вашего оружия."},{"p":"Убийца великанов. Если Большое или еще большее существо в пределах 5 футов попадает или промахивается по вам атакой, вы можете реакцией атаковать это существо сразу после его атаки, при условии, что вы можете видеть его."},{"p":"Убийца колоссов. Ваше упорство может повергнуть самых мощных врагов. Если вы попадаете по существу атакой оружием, это существо получает дополнительный урон 1к8, если его хиты уже ниже максимума. Вы можете причинить этот дополнительный урон только один раз в ход."}]},"subprev:Следопыт:Повелитель зверей":{"title":"Повелитель зверей","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Спутник следопыта"},{"p":"Вы получаете Зверя-спутника, который сопровождает вас во время приключений и обучен сражаться вместе с вами. Выберите Зверя, с размером не больше Среднего, ПО которого 1/4 или ниже (Книга игрока представляет параметры ястреба, мастиффа и пантеры в качестве примеров). Добавьте свой бонус мастерства к КД, броскам атаки и урона Зверя, а также к спасброскам и навыкам, которыми он владеет. Максимум его хитов равен его обычному максимуму или вашему четырёхкратному уровню следопыта, в зависимости от того, что выше."},{"p":"Зверь подчиняется вашим командам так хорошо, как только может. Он совершает ход с вашей инициативой. Как любые другие существа, Зверь может тратить Кости Хитов во время короткого отдыха. Во время своего хода вы можете устно командовать Зверем, куда ему двигаться (для этого не требуется никаких действий от вас). Вы можете действием дать устную команду Зверю совершить Атаку, Отход, Помощь, Рывок. Если вы не даёте команду, Зверь совершает действие Уклонения. Если у вас есть умение «Дополнительная атака», вы можете сами совершить одну атаку оружием, когда приказываете Зверю совершить действие Атака."},{"p":"Если вы недееспособны или отсутствуете, зверь действует самостоятельно, сосредотачиваясь на защите вас и себя. Зверю не требуется ваша команда для использования реакции, вроде провоцированной атаки"},{"p":"Путешествуя по избранной местности только вдвоём со Зверем, вы можете передвигаться скрытно в нормальном темпе."},{"p":"Если Зверь умирает, вы можете получить другого, потратив 8 часов на волшебное связывание себя со Зверем, не враждебным к вам, того же вида, либо другого."},{"h":"Первичный спутник"},{"p":"Вы магическим образом призываете первичного зверя, который черпает силу из вашей связи с природой. Зверь дружелюбен к вам и вашим союзникам, а также подчиняется вашим командам. Выберите одного из следующих существ: земной зверь, морской зверь или небесный зверь. Блоки статистики этих существ используют ваш бонус мастерства (БМ) в некоторых местах. Вы также определяете внешний вид существа в соответствии с типом Зверя и его блоком статистики. Какой бы вид вы ни выбрали, Зверь несёт на себе метки, указывающие на его мистическое происхождение."},{"p":"В бою Зверь действует во время вашего хода. Он может перемещаться и использовать свою реакцию самостоятельно, но единственное действие, которое он может совершать в свой ход, — это Уклонение, если только вы не используете своё бонусное действие, чтобы приказать ему сделать что-то другое. Это действие может быть одним из действий из его блока статистики или любым другим действием. Вы также можете пожертвовать одной из своих атак, когда совершаете действие Атака, и приказать Зверю совершить действие Атака. Если вы недееспособны, то Зверь может использовать любое действие по своему усмотрению, а не только Уклонение."},{"p":"Если Зверь погибает, то в течение часа вы можете действием прикоснуться к нему и использовать ячейку заклинания 1-го уровня или выше. Зверь возвращается к жизни через 1 минуту, восстанавливая все свои хиты."},{"p":"Когда вы закончите продолжительный отдых, вы можете призвать другого первичного зверя. Новый Зверь появляется в свободном пространстве в пределах 5 футов от вас, и вы выбираете его внешний вид и блок статистики. Если у вас уже есть Зверь от этого умения, то он исчезает, когда появляется новый. Зверь исчезает, если вы умираете."}]},"subprev:Следопыт:Странник горизонта":{"title":"Странник горизонта","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Магия странников горизонта"},{"p":"Вы узнаете дополнительные заклинания, когда достигнете определенных уровней в этом классе, как показано в таблице «Заклинания странника горизонта». Заклинания считаются для вас заклинаниями следопыта, и они не учитываются при подсчёте известных вам заклинаний следопыта."},{"t":[["3","защита от зла и добра"],["5","туманный шаг"],["9","ускорение"],["13","изгнание"],["17","круг телепортации"]],"head":["Уровень","Заклинание"]},{"h":"Обнаружить портал"},{"p":"Вы получаете возможность волшебным образом ощутить присутствие планарного портала."},{"p":"Действием вы можете определить расстояние и направление до ближайшего планарного портала в пределах 1 мили от вас."},{"p":"Использовав это умение, вы не можете использовать его повторно до окончания короткого или продолжительного отдыха. Примеры планарных порталов см. в разделе «Путешествия по планам» главы 2 «Руководства Мастера»."},{"h":"Планарный воин"},{"p":"Вы учитесь использовать энергию мультивселенной, чтобы усиливать ваши атаки."},{"p":"Бонусным действием выберите одно существо, которое вы можете видеть в пределах 30 футов. В следующий раз, когда вы попадёте по этому существу оружием на этом ходу, весь урон, причинённый атакой, становится уроном силовым полем, и существо получает дополнительно 1к8 урона силовым полем."},{"p":"Когда вы достигаете 11-го уровня в этом классе, дополнительный урон увеличивается до 2к8."}]},"subprev:Следопыт:Сумрачный охотник":{"title":"Сумрачный охотник","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Магия сумрачного охотника"},{"p":"Вы узнаете дополнительные заклинания, когда достигаете определённых уровней в этом классе, как показано в таблице заклинаний Сумрачный охотник. Заклинания считаются заклинаниями Следопыта для вас, но они не учитываются при подсчёте известных вам заклинаний следопыта."},{"t":[["3","маскировка"],["5","трюк с верёвкой"],["9","ужас"],["13","высшая невидимость"],["17","притворство"]],"head":["Уровень","Заклинание"]},{"h":"Угроза из засады"},{"p":"Вы овладеваете мастерством засад. Вы можете добавить к броску инициативы бонус, равный вашему модификатору Мудрости."},{"p":"В начале вашего первого хода в каждом бою ваша скорость ходьбы увеличивается на 10 футов до конца этого хода. Если вы совершаете действие Атаки в этот ход, вы можете совершить одну дополнительную атаку оружием частью этого действия."},{"p":"Если эта атака попадает, цель получает дополнительно 1к8 урона такого же типа, что и урон оружия."},{"h":"Теневой взор"},{"p":"Вы получаете тёмное зрение в пределах 60 футов. Если вы имеете тёмное зрение от вашей расы, его дистанция увеличивается на 30 футов. Вы также сведущи в уклонении от существ, которые полагаются на тёмное зрение. Находясь во тьме, вы невидимы для любого существа, полагающегося на тёмное зрение, чтобы увидеть вас в этой темноте."}]},"subprev:Следопыт:Убийца чудовищ":{"title":"Убийца чудовищ","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Магия убийцы чудовищ"},{"p":"Вы узнаёте дополнительные заклинания, когда вы достигнете определенных уровней в этом классе, как показано в таблице «Заклинания убийцы чудовищ». Заклинания считаются для вас заклинаниями следопыта, и они не учитываются при подсчёте известных вам заклинаний следопыта."},{"t":[["3","защита от зла и добра"],["5","область истины"],["9","магический круг"],["13","изгнание"],["17","удержание чудовища"]],"head":["Уровень","Заклинание"]},{"h":"Охотничьи чувства"},{"p":"Вы получаете способность оценить существо и определить, как лучше всего навредить ему. Действием выберите одно существо, которое вы можете видеть в пределах 60 футов. Вы мгновенно узнаёте, имеет ли существо какие-либо иммунитеты, сопротивления или уязвимости, и какие они. Если существо скрыто от магии Прорицания, то вы чувствуете, что у него нет иммунитетов, сопротивлений или уязвимостей."},{"p":"Вы можете использовать это умение количество раз равное модификатору вашей Мудрости (минимум 1). Вы восстанавливаете все потраченные использования после окончания короткого или продолжительного отдыха."},{"h":"Добыча убийцы"},{"p":"Вы можете сфокусировать свой гнев на одном враге, увеличивая урон, который вы ему причиняете."},{"p":"Бонусным действием вы выбираете целью этого умения одно существо, которое можете видеть в пределах 60 футов. На каждом ходу, когда вы первый раз попадаете по этой цели атакой оружием, она получает дополнительно 1к6 урона от оружия."},{"p":"Это преимущество действует до окончания вашего короткого или продолжительного отдыха. Оно заканчивается раньше, если вы выбираете другое существо."}]},"subprev:Следопыт:Странник фей":{"title":"Странник фей","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Ужасающие удары"},{"p":"Вы усиливаете свои атаки с помощью разрушающей разум магии. Вы черпаете её из сумрачных пустот Страны Фей. Когда вы попадаете атакой по цели, вы можете нанести дополнительно 1к4 урона психической энергией. Существо может получить этот дополнительный урон только один раз за ход."},{"p":"Дополнительный урон увеличивается до 1к6, когда вы достигаете 11-го уровня в этом классе."},{"h":"Магия странника фей"},{"p":"Когда вы достигаете определённого уровня, вы узнаёте новые заклинания в этом классе, как показано в таблице «Заклинания странника фей». Для вас они считаются заклинаниями следопыта, однако они не учитываются в общем количестве заклинаний, которые вы знаете."},{"h":"Заклинания странника фей"},{"t":[["3","очарование личности"],["5","туманный шаг"],["9","рассеивание магии"],["13","переносящая дверь"],["17","фальшивый двойник"]],"head":["Уровень следопыта","Заклинание"]},{"p":"Вы также наделены сверхъестественным благословением, дарованным вам дружественной феей или священным местом фейской силы. Выберите свое благословение из таблицы «Дары Страны Фей» или бросьте к6, чтобы определить его случайным образом."},{"h":"Дары Страны Фей"},{"t":[["1","Иллюзорные бабочки порхают вокруг вас, когда вы совершаете короткий или продолжительный отдых."],["2","Каждый рассвет в ваших волосах распускается свежий сезонный цветок."],["3","Вы едва заметно пахнете корицей, лавандой, мускатным орехом или другой приятной травой или специей."],["4","Ваша тень танцует, когда никто не смотрит прямо на неё."],["5","На вашей голове растут аккуратные или большие рога."],["6","На рассвете ваш цвет волос и кожи меняют свой цвет в соответствие сезону."]],"head":["к6","Дар"]},{"h":"Потустороннее очарование"},{"p":"Ваши фейские качества даруют вам сверхъестественное очарование. Каждый раз, когда вы совершаете проверку Харизмы, вы получаете бонус, равный вашему модификатору Мудрости (минимум + 1)."},{"p":"В дополнение вы получаете владение одним из навыков по вашему выбору: Выступление, Обман или Убеждение."}]},"subprev:Следопыт:Хранитель роя":{"title":"Хранитель роя","source":"dnd.su","full":[{"p":"Умения 3-го уровня:"},{"h":"Собранный рой"},{"p":"Рой бестелесных духов природы связал себя с вами и может помогать вам в сражениях. Пока вы живы, рой остается в пределах занимаемого вами пространства, ползая по вам, летая вокруг вас, пробиваясь через вашу одежду или проносясь на большой скорости рядом с вами. Вы определяете его внешний вид самостоятельно или с помощью броска по таблице «Внешний вид роя»."},{"h":"Внешний вид роя"},{"t":[["1","Роящиеся насекомые"],["2","Миниатюрные ветвистые заразы"],["3","Порхающие птицы"],["4","Игривые пикси"]],"head":["к4","Внешний вид"]},{"p":"Один раз в каждый свой ход вы можете призвать рой помочь вам одним из следующих способов сразу же после того, как вы попадёте по существу атакой:"},{"p":"Цель атаки получает 1к6 колющего урона от роя."},{"p":"Цель атаки должна преуспеть в cпасброске Силы против Сл ваших заклинаний, иначе будет перемещена роем на 15 футов по горизонтали в направлении по вашему выбору."},{"p":"Рой перемещает вас на 5 футов по горизонтали в направлении по вашему выбору."},{"h":"Магия хранителя роя"},{"p":"Вы изучаете заговор волшебная рука, если не знали его до этого. Когда вы накладываете это заклинание, волшебная рука выглядит как рой духов природы."},{"p":"Вы также изучаете дополнительное заклинание 1-го уровня или выше, когда достигаете определённых уровней в этом классе, как показано в таблице «Заклинания хранителя роя». Для вас они считаются заклинаниями следопыта, однако они не учитываются в общем количестве заклинаний, которые вы знаете."},{"h":"Заклинания хранителя роя"},{"t":[["3","волшебная рука, огонь фей"],["5","паутина"],["9","газообразная форма"],["13","магический глаз"],["17","нашествие насекомых"]],"head":["Уровень следопыта","Заклинания"]}]}};
